"""Platform runtime manager - skeleton only (no implementation).

This module defines the interface for runtime management.
Implementation will be added in future WOs.
"""

from pathlib import Path
from typing import Any, Protocol


class RuntimeManager(Protocol):
    """Protocol defining runtime management interface."""

    def ensure_initialized(self, repo_id: str) -> Path:
        """Ensure runtime is initialized for repo."""
        ...

    def get_runtime_dir(self, repo_id: str) -> Path:
        """Get runtime directory for repo."""
        ...

    def is_initialized(self, repo_id: str) -> bool:
        """Check if runtime is initialized."""
        ...

    def cleanup(self, repo_id: str) -> None:
        """Cleanup runtime resources."""
        ...


class DaemonManager(Protocol):
    """Protocol defining daemon management interface."""

    def start(self, repo_id: str) -> bool:
        """Start daemon for repo."""
        ...

    def stop(self, repo_id: str) -> bool:
        """Stop daemon for repo."""
        ...

    def status(self, repo_id: str) -> dict[str, Any]:
        """Get daemon status."""
        ...

    def restart(self, repo_id: str) -> bool:
        """Restart daemon for repo."""
        ...


class HealthChecker(Protocol):
    """Protocol defining health check interface."""

    def check(self, repo_id: str) -> dict[str, Any]:
        """Perform health check."""
        ...

import os
import signal
import subprocess
import sys
import time
from dataclasses import dataclass
from pathlib import Path
from typing import Callable, Optional


@dataclass
class DaemonStatus:
    running: bool
    pid: Optional[int] = None
    socket_path: Optional[Path] = None
    error_message: Optional[str] = None


ALLOWED_BASES = [
    Path("~/.local/share/trifecta").expanduser().resolve(),
    Path("~/.config/trifecta").expanduser().resolve(),
    Path("~/.cache/trifecta").expanduser().resolve(),
]


def is_runtime_dir_allowed(path: Path, allowed_bases: Optional[list[Path]] = None) -> bool:
    try:
        resolved = path.resolve()
        bases = ALLOWED_BASES if allowed_bases is None else allowed_bases
        return any(resolved.is_relative_to(base.resolve()) for base in bases)
    except Exception:
        return False


def _is_path_safe(path: Path) -> bool:
    return is_runtime_dir_allowed(path, ALLOWED_BASES)


def _lsp_request_timeout_env(default: str = "30") -> str:
    raw_value = os.environ.get("TRIFECTA_LSP_REQUEST_TIMEOUT")
    if raw_value is None:
        return default
    try:
        float(raw_value)
        return raw_value
    except ValueError:
        return default


class DaemonManager:
    DAEMON_TTL_IDLE = 300
    DAEMON_START_TIMEOUT = 5

    def __init__(self, runtime_dir: Path, repo_root: Optional[Path] = None) -> None:
        self._runtime_dir = runtime_dir
        self._repo_root = repo_root if repo_root is not None else runtime_dir
        self._log_path = runtime_dir / "daemon" / "log"
        # Resolve fingerprint to match DaemonRunner paths (daemon_paths as SSOT)
        from src.domain.segment_resolver import resolve_segment_ref
        from src.infrastructure.daemon_paths import (
            get_daemon_socket_path,
            get_daemon_pid_path,
            get_daemon_lock_path,
        )
        fp = resolve_segment_ref(str(self._repo_root)).fingerprint
        self._socket_path = get_daemon_socket_path(fp)
        self._pid_path = get_daemon_pid_path(fp)
        self._lock_path = get_daemon_lock_path(fp)

    def start(self) -> tuple[bool, Optional[str]]:
        """Start daemon. Returns True if daemon is running after call.

        Note: Returns True both if daemon was already running and if
        it was just started. Use is_running() before start() to distinguish.
        """
        if self.is_running():
            return True, None
        if not _is_path_safe(self._runtime_dir):
            return False, "Invalid runtime directory"
        # Check for directory blocking socket path
        if self._socket_path.exists() and not self._socket_path.is_socket():
            return False, f"Socket path blocked by non-socket file: {self._socket_path}"

        self._runtime_dir.mkdir(parents=True, exist_ok=True)
        self._log_path.parent.mkdir(parents=True, exist_ok=True)

        # Fase 4: singleton lock to prevent concurrent starts
        if not self._acquire_singleton_lock():
            return False, "Failed to acquire singleton lock"

        log_file = self._log_path.open("a")
        python_exe = sys.executable
        import src.infrastructure.cli as cli_module

        cli_path = Path(cli_module.__file__)
        env = os.environ.copy()
        env["TRIFECTA_RUNTIME_DIR"] = str(self._runtime_dir)
        env["TRIFECTA_REPO_ROOT"] = str(self._repo_root.resolve())
        trifecta_root = Path(__file__).parent.parent.parent.resolve()
        env["PYTHONPATH"] = f"{trifecta_root}:{self._repo_root.resolve()}:{env.get('PYTHONPATH', '')}"
        # Pass TTL if configured (Fase 4 hardening)
        if self.DAEMON_TTL_IDLE > 0:
            env["TRIFECTA_DAEMON_TTL"] = str(self.DAEMON_TTL_IDLE)
        env["TRIFECTA_LSP_REQUEST_TIMEOUT"] = _lsp_request_timeout_env()
        proc = subprocess.Popen(
            [python_exe, str(cli_path), "daemon", "run"],
            cwd=str(self._runtime_dir),
            stdout=log_file,
            stderr=subprocess.STDOUT,
            start_new_session=True,
            env=env,
        )
        try:
            for _ in range(self.DAEMON_START_TIMEOUT * 10):
                # Check if process is still alive
                if proc.poll() is not None:
                    # Process died, try to get error from log
                    error_info = "Daemon process exited prematurely"
                    try:
                        if self._log_path.exists():
                            lines = self._log_path.read_text().splitlines()
                            if lines:
                                error_info = f"{error_info}: {lines[-1]}"
                    except Exception:
                        pass
                    return False, error_info

                if self._socket_path.exists():
                    self._pid_path.write_text(str(proc.pid))
                    return True, None
                time.sleep(0.1)
            # Timeout — kill orphaned subprocess
            try:
                proc.kill()
                proc.wait(timeout=2)
            except (ProcessLookupError, OSError):
                pass
            return False, "Startup timed out"
        finally:
            self._release_singleton_lock()

    def stop(self) -> bool:
        if not self.is_running():
            return True
        try:
            pid = int(self._pid_path.read_text().strip())
            os.kill(pid, signal.SIGTERM)
            for _ in range(50):
                if not self.is_running():
                    return True
                time.sleep(0.1)
            os.kill(pid, signal.SIGKILL)
            time.sleep(0.1)
            return not self.is_running()
        except (FileNotFoundError, ProcessLookupError, ValueError):
            return True
        finally:
            self._cleanup_files()

    def restart(self) -> bool:
        self.stop()
        return self.start()

    def status(self) -> DaemonStatus:
        pid = None
        if self._pid_path.exists():
            try:
                pid = int(self._pid_path.read_text().strip())
                os.kill(pid, 0)
            except (ProcessLookupError, PermissionError, ValueError):
                pid = None
        running = pid is not None and self._socket_path.exists()
        return DaemonStatus(
            running=running,
            pid=pid,
            socket_path=self._socket_path if running else None,
        )

    def is_running(self) -> bool:
        return self.status().running

    def _read_daemon_pid(self) -> Optional[int]:
        """Read the daemon PID file, returning None when it is missing or invalid."""
        try:
            return int(self._pid_path.read_text(encoding="utf-8").strip())
        except (FileNotFoundError, OSError, ValueError):
            return None

    @staticmethod
    def _is_pid_alive(pid: int) -> bool:
        """Check process liveness with signal 0, treating permission errors as alive."""
        try:
            os.kill(pid, 0)
        except ProcessLookupError:
            return False
        except PermissionError:
            return True
        else:
            return True

    def _lock_owner_is_alive(self) -> bool:
        """Return whether the PID recorded for the daemon still points to a live process."""
        pid = self._read_daemon_pid()
        return pid is not None and self._is_pid_alive(pid)

    def _wait_for_lock_release(
        self, bind_lock: Callable[[], object], timeout_seconds: float | None = None
    ) -> bool:
        """Poll for lock release up to timeout_seconds and acquire it if it becomes free."""
        timeout = max(0, self.DAEMON_START_TIMEOUT if timeout_seconds is None else timeout_seconds)
        deadline = time.monotonic() + timeout
        while time.monotonic() < deadline:
            if self.is_running() or self._lock_owner_is_alive():
                return False
            try:
                self._singleton_lock = bind_lock()
                return True
            except OSError:
                time.sleep(0.1)
        return False

    def _acquire_singleton_lock(self) -> bool:
        """Acquire exclusive lock to prevent concurrent daemon starts.

        Uses socket bind as atomic singleton check. If bind fails,
        another instance is already running, or a stale lock path exists.

        Returns:
            True if lock acquired, False if another instance holds it.
        """
        import socket as _socket

        def _bind_lock() -> _socket.socket:
            lock_socket = _socket.socket(_socket.AF_UNIX, _socket.SOCK_DGRAM)
            lock_socket.bind(str(self._lock_path))
            return lock_socket

        try:
            self._singleton_lock = _bind_lock()
            return True
        except OSError:
            if self.is_running() or self._lock_owner_is_alive():
                return False
            if self._wait_for_lock_release(_bind_lock):
                return True
            if self.is_running() or self._lock_owner_is_alive():
                return False
            if self._lock_path.exists():
                try:
                    self._lock_path.unlink()
                except FileNotFoundError:
                    # Another process may clear the stale path after our last check.
                    # Fall through to retry lock acquisition below.
                    pass
                except OSError:
                    return False
            try:
                self._singleton_lock = _bind_lock()
                return True
            except OSError:
                pass
            return False

    def _release_singleton_lock(self) -> None:
        """Release singleton lock."""
        if hasattr(self, "_singleton_lock") and self._singleton_lock:
            try:
                self._singleton_lock.close()
            except Exception:
                pass
            try:
                self._lock_path.unlink()
            except FileNotFoundError:
                pass

    def _cleanup_files(self) -> None:
        for p in [self._pid_path, self._socket_path, self._lock_path]:
            try:
                p.unlink()
            except FileNotFoundError:
                pass

"""Platform registry - contract only (no implementation).

This module defines the interface for the repository registry.
Implementation lives in repo_store.py (WO-0043).
"""

from pathlib import Path
from typing import Protocol


class RepoRecord:
    """Immutable record of a registered repository."""

    __slots__ = ("_repo_id", "_root_path", "_created_at", "_last_accessed")

    def __init__(
        self, repo_id: str, root_path: Path, created_at: str, last_accessed: str | None = None
    ):
        object.__setattr__(self, "_repo_id", repo_id)
        object.__setattr__(self, "_root_path", root_path)
        object.__setattr__(self, "_created_at", created_at)
        object.__setattr__(self, "_last_accessed", last_accessed)

    @property
    def repo_id(self) -> str:
        return self._repo_id

    @property
    def root_path(self) -> Path:
        return self._root_path

    @property
    def created_at(self) -> str:
        return self._created_at

    @property
    def last_accessed(self) -> str | None:
        return self._last_accessed


class Registry(Protocol):
    """Protocol defining the registry interface."""

    def add(self, repo_id: str, root_path: Path) -> RepoRecord:
        """Register a repository."""
        ...

    def get(self, repo_id: str) -> RepoRecord | None:
        """Get repository by ID."""
        ...

    def list_all(self) -> list[RepoRecord]:
        """List all registered repositories."""
        ...

    def delete(self, repo_id: str) -> bool:
        """Remove repository from registry."""
        ...

from dataclasses import dataclass
from pathlib import Path


@dataclass
class HealthResult:
    healthy: bool
    score: float
    checks: dict[str, bool]


class HealthChecker:
    def __init__(self, runtime_dir: Path) -> None:
        self._runtime_dir = runtime_dir

    def check(self) -> HealthResult:
        checks = {}
        checks["runtime_exists"] = self._runtime_dir.exists()
        checks["daemon_healthy"] = self._check_daemon()
        score = sum(checks.values()) / len(checks) * 100
        return HealthResult(healthy=all(checks.values()), score=score, checks=checks)

    def _check_daemon(self) -> bool:
        socket_path = self._runtime_dir / "daemon" / "socket"
        pid_path = self._runtime_dir / "daemon" / "pid"
        if not socket_path.exists() or not pid_path.exists():
            return False
        try:
            import os

            pid = int(pid_path.read_text().strip())
            os.kill(pid, 0)
            return True
        except (ProcessLookupError, PermissionError, ValueError):
            return False

"""Platform-layer exceptions for Trifecta V1 runtime.

These exceptions handle errors related to:
- Repository registration and lookup
- Daemon lifecycle management
- Runtime state and health
"""

from pathlib import Path


class PlatformError(Exception):
    """Base exception for all platform-related errors."""

    pass


class RepoNotFoundError(PlatformError):
    """Raised when a requested repository is not found in the registry."""

    def __init__(self, repo_id: str, message: str | None = None):
        self.repo_id = repo_id
        if message is None:
            message = f"Repository not found: '{repo_id}'"
        super().__init__(message)


class SegmentNotFoundError(PlatformError):
    """Raised when a segment cannot be resolved from the given path."""

    def __init__(self, path: Path | str, message: str | None = None):
        self.path = Path(path)
        if message is None:
            message = f"Segment not found at path: '{self.path}'"
        super().__init__(message)


class DaemonError(PlatformError):
    """Base exception for daemon-related errors."""

    pass


class DaemonStartError(DaemonError):
    """Raised when the daemon fails to start."""

    def __init__(self, reason: str, message: str | None = None):
        self.reason = reason
        if message is None:
            message = f"Failed to start daemon: {reason}"
        super().__init__(message)


class DaemonStopError(DaemonError):
    """Raised when the daemon fails to stop."""

    def __init__(self, reason: str, message: str | None = None):
        self.reason = reason
        if message is None:
            message = f"Failed to stop daemon: {reason}"
        super().__init__(message)


class DaemonNotRunningError(DaemonError):
    """Raised when daemon operation requires running daemon but it's not active."""

    def __init__(self, repo_id: str | None = None, message: str | None = None):
        self.repo_id = repo_id
        if message is None:
            if repo_id:
                message = f"Daemon not running for repository: '{repo_id}'"
            else:
                message = "Daemon is not running"
        super().__init__(message)


class HealthCheckError(PlatformError):
    """Raised when health check fails."""

    def __init__(self, check_name: str, message: str | None = None):
        self.check_name = check_name
        if message is None:
            message = f"Health check failed: {check_name}"
        super().__init__(message)


class RuntimeError(PlatformError):
    """Base exception for runtime-related errors."""

    pass


class RuntimeNotInitializedError(RuntimeError):
    """Raised when runtime is accessed before initialization."""

    def __init__(self, repo_id: str, message: str | None = None):
        self.repo_id = repo_id
        if message is None:
            message = f"Runtime not initialized for repository: '{repo_id}'"
        super().__init__(message)


class StorageError(PlatformError):
    """Base exception for storage-related errors."""

    pass


class DatabaseError(StorageError):
    """Raised when database operation fails."""

    def __init__(self, db_path: Path, reason: str, message: str | None = None):
        self.db_path = db_path
        self.reason = reason
        if message is None:
            message = f"Database error at '{db_path}': {reason}"
        super().__init__(message)

from __future__ import annotations

import json
from pathlib import Path
from typing import Any

from src.domain.linear_models import LinearPolicy


_SEVERITY_ORDER = {"INFO": 1, "WARN": 2, "FATAL": 3}


def classify_drift(changed_fields: set[str], policy: LinearPolicy) -> str:
    normalized = set(changed_fields)
    if "state" in normalized:
        normalized.add("status_critical")

    highest = "INFO"
    for sev in ("INFO", "WARN", "FATAL"):
        mapped = set(policy.drift_severity.get(sev, ()))
        if normalized & mapped and _SEVERITY_ORDER[sev] > _SEVERITY_ORDER[highest]:
            highest = sev
    return highest


def diff_payload(projected: dict[str, Any], current: dict[str, Any]) -> dict[str, dict[str, Any]]:
    keys = sorted(set(projected.keys()) | set(current.keys()))
    diffs: dict[str, dict[str, Any]] = {}
    for key in keys:
        if projected.get(key) != current.get(key):
            diffs[key] = {"projected": projected.get(key), "current": current.get(key)}
    return diffs


def write_reconcile_reports(
    root: Path,
    findings: list[dict[str, Any]],
    policy_version: str,
) -> tuple[Path, Path]:
    sync_dir = root / "_ctx" / "linear_sync"
    sync_dir.mkdir(parents=True, exist_ok=True)

    ordered = sorted(findings, key=lambda x: x.get("wo_id", ""))
    json_path = sync_dir / "reconcile_report.json"
    md_path = sync_dir / "reconcile_report.md"

    payload = {
        "policy_version": policy_version,
        "findings": ordered,
    }
    json_path.write_text(json.dumps(payload, indent=2, sort_keys=True) + "\n", encoding="utf-8")

    lines = ["# Linear Reconcile Report", "", f"Policy version: `{policy_version}`", ""]
    if not ordered:
        lines.append("No drift detected.")
    else:
        for item in ordered:
            wo_id = item.get("wo_id", "unknown")
            sev = item.get("severity", "INFO")
            issue = item.get("linear_issue_id", "")
            lines.append(f"## {wo_id}")
            lines.append(f"- Severity: `{sev}`")
            if issue:
                lines.append(f"- Linear Issue: `{issue}`")
            changed = item.get("changed_fields", [])
            if changed:
                lines.append(f"- Changed Fields: {', '.join(changed)}")
            lines.append("")

    md_path.write_text("\n".join(lines).rstrip() + "\n", encoding="utf-8")
    return json_path, md_path

import sqlite3
from pathlib import Path
from typing import Any


class QueryUseCase:
    def __init__(self, runtime_dir: Path) -> None:
        self._runtime_dir = runtime_dir
        self._search_db = runtime_dir / "search.db"

    def execute(self, query: str, limit: int = 10) -> dict[str, Any]:
        if not self._search_db.exists():
            return {"status": "error", "message": "No index found. Run index first."}
        conn = sqlite3.connect(self._search_db)
        conn.row_factory = sqlite3.Row
        cur = conn.execute(
            "SELECT file, snippet(search_fts, 1, '<b>', '</b>', '...', 64) as snippet "
            "FROM search_fts WHERE search_fts MATCH ? ORDER BY bm25(search_fts) LIMIT ?",
            (query, limit),
        )
        results = [dict(row) for row in cur.fetchall()]
        conn.close()
        return {"status": "ok", "query": query, "results": results, "count": len(results)}

from pathlib import Path
from typing import Any, Optional

from src.platform.daemon_manager import DaemonManager
from src.platform.health import HealthChecker


class DaemonUseCase:
    def __init__(self, runtime_dir: Path, repo_root: Optional[Path] = None) -> None:
        self._manager = DaemonManager(runtime_dir, repo_root=repo_root)
        self._health = HealthChecker(runtime_dir)

    def start(self) -> dict[str, Any]:
        ok = self._manager.start()
        return {"status": "ok" if ok else "error", "running": ok}

    def stop(self) -> dict[str, Any]:
        ok = self._manager.stop()
        return {"status": "ok", "running": not ok}

    def restart(self) -> dict[str, Any]:
        ok = self._manager.restart()
        return {"status": "ok" if ok else "error", "running": ok}

    def status(self) -> dict[str, Any]:
        status = self._manager.status()
        health = self._health.check()
        return {
            "status": "ok",
            "running": status.running,
            "pid": status.pid,
            "socket": str(status.socket_path) if status.socket_path else None,
            "health": {"healthy": health.healthy, "score": health.score},
        }

from pathlib import Path
from dataclasses import dataclass, field
from typing import Optional, List, Any
from src.domain.result import Result, Ok, Err
from src.domain.ast_models import ASTError, ASTErrorCode


@dataclass
class SymbolResolveResult:
    """Result of symbol resolution."""

    resolved: bool = False
    ambiguous: bool = False
    file: Optional[str] = None
    start_line: Optional[int] = None
    end_line: Optional[int] = None
    matches: int = 0
    candidates: List[Any] = field(default_factory=list)


class SymbolQuery:
    def __init__(self, kind: str, path: str, member: Optional[str] = None):
        self.kind = kind
        self.path = path
        self.member = member

    @classmethod
    def parse(cls, uri: str) -> Result["SymbolQuery", ASTError]:
        if not uri.startswith("sym://python/"):
            return Err(
                ASTError(code=ASTErrorCode.INVALID_URI, message="URI must start with sym://python/")
            )

        remainder = uri[len("sym://python/") :]
        parts = remainder.split("/", 1)
        if len(parts) != 2:
            return Err(
                ASTError(code=ASTErrorCode.INVALID_URI, message="URI must contain kind and path")
            )

        kind = parts[0]
        path_member = parts[1]

        if kind not in ("mod", "type"):
            return Err(ASTError(code=ASTErrorCode.INVALID_URI, message="Kind must be mod or type"))

        member = None
        if "#" in path_member:
            path_only, member = path_member.split("#", 1)
        else:
            path_only = path_member

        if kind == "mod" and member:
            return Err(
                ASTError(
                    code=ASTErrorCode.INVALID_URI, message="Kind 'mod' should not have fragment"
                )
            )

        return Ok(cls(kind, path_only, member))


class Candidate:
    def __init__(
        self,
        file_rel: str,
        kind: str,
        start_line: Optional[int] = None,
        end_line: Optional[int] = None,
    ):
        self.file_rel = file_rel
        self.kind = kind
        self.start_line = start_line
        self.end_line = end_line


class SymbolResolver:
    def __init__(self, builder: Any, root: Optional[Path] = None):
        self.builder = builder
        self.root = root or Path.cwd()

    def resolve(self, query: SymbolQuery) -> Result[Candidate, ASTError]:
        # Simple resolution logic
        # 1. Exact file
        candidate_file = self.root / f"{query.path}.py"
        candidate_init = self.root / query.path / "__init__.py"

        file_exists = candidate_file.exists() and candidate_file.is_file()
        init_exists = candidate_init.exists() and candidate_init.is_file()

        if file_exists and init_exists:
            return Err(
                ASTError(code=ASTErrorCode.AMBIGUOUS_SYMBOL, message="Ambiguous module path")
            )

        if file_exists:
            return Ok(Candidate(f"{query.path}.py", "mod"))
        elif init_exists:
            return Ok(Candidate(f"{query.path}/__init__.py", "mod"))

        # If member is present, we might be looking for a type in a file
        # But for strictly restoring what works:
        return Err(
            ASTError(
                code=ASTErrorCode.FILE_NOT_FOUND, message=f"Could not find module for {query.path}"
            )
        )

from pathlib import Path

from src.domain.segment_resolver import SegmentRef, resolve_segment_ref
from src.infrastructure.graph_store import (
    GraphStore,
    GraphStoreAccessError,
)


class GraphService:
    def __init__(self, store: GraphStore | None = None) -> None:
        self._store = store

    def status(self, segment: Path | str) -> dict[str, object]:
        segment_ref = resolve_segment_ref(segment)
        db_path = GraphStore.db_path_for_segment(segment_ref.root_abs, segment_ref.id)
        if self._uses_injected_store(db_path):
            status = self._store.get_status(segment_ref.id)
        else:
            status = GraphStore.probe_status(db_path, segment_ref.id)
        return {"status": "ok", **status.to_dict()}

    def search(self, segment: Path | str, query: str, limit: int = 20) -> dict[str, object]:
        # Search stays fuzzy on purpose; exact symbol resolution is only for callers/callees.
        resolved = self._resolve_existing(segment, required_tables=GraphStore.SEARCH_REQUIRED_TABLES)
        if resolved is None:
            segment_ref = resolve_segment_ref(segment)
            return {"status": "ok", "segment_id": segment_ref.id, "query": query, "nodes": []}
        segment_ref, store = resolved
        nodes = store.search_nodes(segment_ref.id, query, limit=limit)
        return {
            "status": "ok",
            "segment_id": segment_ref.id,
            "query": query,
            "nodes": [node.to_dict() for node in nodes],
        }

    def callers(self, segment: Path | str, symbol: str) -> dict[str, object]:
        return self._related(segment, symbol, reverse=True)

    def callees(self, segment: Path | str, symbol: str) -> dict[str, object]:
        return self._related(segment, symbol, reverse=False)

    def related_terms(self, segment: Path | str, query: str) -> dict[str, object]:
        resolved = self._resolve_existing(segment, required_tables=GraphStore.SEARCH_REQUIRED_TABLES)
        if resolved is None:
            segment_ref = resolve_segment_ref(segment)
            return {"status": "ok", "segment_id": segment_ref.id, "terms": []}
        segment_ref, store = resolved
        nodes = store.search_nodes(segment_ref.id, query, limit=1)
        if not nodes:
            return {"status": "ok", "segment_id": segment_ref.id, "terms": []}
        first = nodes[0]
        return {
            "status": "ok",
            "segment_id": segment_ref.id,
            "terms": [first.symbol_name, first.file_rel],
        }

    def _related(self, segment: Path | str, symbol: str, reverse: bool) -> dict[str, object]:
        try:
            resolved = self._resolve_existing(segment, required_tables=GraphStore.RELATION_REQUIRED_TABLES)
        except GraphStoreAccessError as exc:
            exc.symbol = symbol
            raise
        if resolved is None:
            segment_ref = resolve_segment_ref(segment)
            return {
                "status": "ok",
                "segment_id": segment_ref.id,
                "symbol": symbol,
                "nodes": [],
            }
        segment_ref, store = resolved
        target_node = self._resolve_related_target(store, segment_ref.id, symbol)
        nodes = (
            store.get_callers_for_node(segment_ref.id, target_node.id)
            if reverse
            else store.get_callees_for_node(segment_ref.id, target_node.id)
        )
        return {
            "status": "ok",
            "segment_id": segment_ref.id,
            "symbol": symbol,
            "nodes": [node.to_dict() for node in nodes],
        }

    def _resolve_related_target(self, store: GraphStore, segment_id: str, symbol: str):
        return store._resolve_target_node(segment_id, symbol)

    def _resolve_existing(
        self,
        segment: Path | str,
        *,
        required_tables: tuple[str, ...],
    ) -> tuple[SegmentRef, GraphStore] | None:
        segment_ref = resolve_segment_ref(segment)
        db_path = GraphStore.db_path_for_segment(segment_ref.root_abs, segment_ref.id)
        if self._uses_injected_store(db_path):
            return segment_ref, self._store
        if not db_path.exists():
            return None
        return segment_ref, GraphStore.open_readonly(
            db_path,
            segment_ref.id,
            required_tables=required_tables,
        )

    def _uses_injected_store(self, expected_db_path: Path) -> bool:
        if self._store is None:
            return False
        store_db_path = self._store.db_path.resolve(strict=False)
        normalized_expected_path = expected_db_path.resolve(strict=False)
        if store_db_path == normalized_expected_path:
            return True
        return (
            store_db_path.parent == normalized_expected_path.parent
            and not expected_db_path.exists()
        )

from __future__ import annotations

from pathlib import Path
from typing import Any

from src.domain.linear_models import LinearPolicy


def _map_priority(value: Any) -> int:
    if isinstance(value, int):
        return value
    if not isinstance(value, str):
        return 3
    v = value.strip().lower()
    mapping = {
        "p0": 1,
        "p1": 2,
        "p2": 3,
        "p3": 4,
        "urgent": 1,
        "high": 2,
        "medium": 3,
        "normal": 3,
        "low": 4,
    }
    return mapping.get(v, 3)


def _render_read_only_section(title: str, lines: list[str]) -> str:
    body = "\n".join(lines) if lines else "(none)"
    return f"### {title} (read-only from Trifecta)\n{body}\n"


def _render_dod(wo: dict[str, Any]) -> list[str]:
    if isinstance(wo.get("dod"), list):
        items: list[str] = []
        for raw in wo["dod"]:
            if isinstance(raw, dict) and isinstance(raw.get("criterion"), str):
                items.append(f"- {raw['criterion']}")
            elif isinstance(raw, str):
                items.append(f"- {raw}")
        return items
    dod_id = wo.get("dod_id")
    if isinstance(dod_id, str) and dod_id:
        return [f"- dod_id: {dod_id}"]
    return []


def _render_verify_commands(wo: dict[str, Any]) -> list[str]:
    verify = wo.get("verify")
    if not isinstance(verify, dict):
        return []
    commands = verify.get("commands")
    if not isinstance(commands, list):
        return []
    return [f"- `{cmd}`" for cmd in commands if isinstance(cmd, str)]


def build_linear_payload(
    wo: dict[str, Any],
    policy: LinearPolicy,
    linear_state_id: str,
    wo_yaml_path: Path,
) -> dict[str, Any]:
    wo_id = str(wo.get("id") or "")
    title = str(wo.get("title") or "")
    objective = str(wo.get("objective") or wo.get("description") or "").strip()

    description_parts = [
        _render_read_only_section("Objective", [objective] if objective else []),
        _render_read_only_section("Definition of Done", _render_dod(wo)),
        _render_read_only_section("Verification Commands", _render_verify_commands(wo)),
        _render_read_only_section("Source", [f"- WO YAML: `{wo_yaml_path}`", f"- WO ID: `{wo_id}`"]),
    ]

    labels = ["trifecta", f"status:{wo.get('status', 'pending')}"]
    epic_id = wo.get("epic_id")
    if isinstance(epic_id, str) and epic_id:
        labels.append(f"epic:{epic_id}")

    owner = wo.get("owner")
    assignee = owner if isinstance(owner, str) and owner else None

    payload = {
        "wo_id": wo_id,
        "title": f"[{wo_id}] {title}".strip(),
        "description": "\n\n".join(description_parts).strip(),
        "priority": _map_priority(wo.get("priority", "medium")),
        "labels": sorted(set(labels)),
        "state": linear_state_id,
        "team": policy.team_id or policy.team_key,
        "status": wo.get("status", "pending"),
        "epic_id": epic_id if isinstance(epic_id, str) else "",
    }
    if assignee:
        payload["assignee"] = assignee
    if policy.project:
        payload["project"] = policy.project

    # Keep only policy-allowed outbound fields + wo_id anchor for remote lookup
    allowed = set(policy.outbound_allow) | {"wo_id", "status", "epic_id", "team"}
    return {k: v for k, v in payload.items() if k in allowed}

import json
from datetime import datetime, timezone
from pathlib import Path
from typing import Any


def _sync_dir(root: Path) -> Path:
    path = root / "_ctx" / "linear_sync"
    path.mkdir(parents=True, exist_ok=True)
    return path


def _journal_path(root: Path) -> Path:
    return _sync_dir(root) / "index.jsonl"


def _state_path(root: Path) -> Path:
    return _sync_dir(root) / "state.json"


def append_journal_event(root: Path, event: dict[str, Any]) -> None:
    entry = {
        "ts": datetime.now(timezone.utc).isoformat(),
        **event,
    }
    line = json.dumps(entry, sort_keys=True, separators=(",", ":"), ensure_ascii=True)
    with _journal_path(root).open("a", encoding="utf-8") as f:
        f.write(line + "\n")


def _rebuild_state_from_journal(root: Path) -> dict[str, dict[str, str]]:
    state: dict[str, dict[str, str]] = {}
    path = _journal_path(root)
    if not path.exists():
        return state

    with path.open("r", encoding="utf-8") as f:
        for raw in f:
            raw = raw.strip()
            if not raw:
                continue
            row = json.loads(raw)
            wo_id = row.get("wo_id")
            if not isinstance(wo_id, str) or not wo_id:
                continue
            issue_id = row.get("linear_issue_id")
            fingerprint = row.get("last_fingerprint")
            policy_version = row.get("policy_version")
            updated_at = row.get("updated_at") or row.get("ts")
            if not all(isinstance(x, str) and x for x in [issue_id, fingerprint, policy_version, updated_at]):
                continue
            state[wo_id] = {
                "linear_issue_id": issue_id,
                "last_fingerprint": fingerprint,
                "policy_version": policy_version,
                "updated_at": updated_at,
            }

    return state


def write_state_snapshot(root: Path, state: dict[str, dict[str, str]]) -> None:
    ordered = {key: state[key] for key in sorted(state.keys())}
    _state_path(root).write_text(
        json.dumps(ordered, indent=2, sort_keys=True, ensure_ascii=True) + "\n",
        encoding="utf-8",
    )


def load_or_rebuild_state(root: Path) -> dict[str, dict[str, str]]:
    path = _state_path(root)
    if path.exists():
        try:
            data = json.loads(path.read_text(encoding="utf-8"))
            if isinstance(data, dict):
                return data
        except json.JSONDecodeError:
            pass

    rebuilt = _rebuild_state_from_journal(root)
    write_state_snapshot(root, rebuilt)
    return rebuilt

"""Query expansion with alias support and weighting."""

from typing import Any, Dict, List, Tuple, Set


class QueryExpander:
    """Expand queries using aliases with weighted terms."""

    MAX_EXTRA_TERMS = 8
    ORIGINAL_WEIGHT = 1.0
    ALIAS_WEIGHT = 0.7

    def __init__(self, aliases: Dict[str, List[str]]):
        """Initialize expander with aliases.

        Args:
            aliases: Dict mapping alias keys to synonym lists
        """
        self.aliases = aliases

    def expand(self, query: str, tokens: List[str]) -> List[Tuple[str, float]]:
        """Expand query using aliases with weights.

        Args:
            query: Normalized query string
            tokens: Query tokens

        Returns:
            List of (term, weight) tuples, capped at MAX_EXTRA_TERMS
        """
        if not self.aliases:
            # No aliases -> return original query only
            return [(query, self.ORIGINAL_WEIGHT)]

        # Start with original query
        terms: List[Tuple[str, float]] = [(query, self.ORIGINAL_WEIGHT)]

        # Track added terms to avoid duplicates
        added_terms: Set[str] = {query}

        # Helper to avoid duplicates and cap terms
        def add_term(term: str, weight: float) -> None:
            if term not in added_terms and len(added_terms) - 1 < self.MAX_EXTRA_TERMS:
                terms.append((term, weight))
                added_terms.add(term)

        # 1. Check full query in keys and synonyms
        # From key -> add all synonyms
        if query in self.aliases:
            for synonym in self.aliases[query]:
                add_term(synonym, self.ALIAS_WEIGHT)

        # From synonym -> add key (reverse lookup)
        for key, synonyms in self.aliases.items():
            if query in synonyms:
                add_term(key, self.ALIAS_WEIGHT)

        # 2. Check each token (if not already found)
        for token in tokens:
            if len(added_terms) - 1 >= self.MAX_EXTRA_TERMS:
                break

            # From key -> add synonyms
            if token in self.aliases:
                for synonym in self.aliases[token]:
                    add_term(synonym, self.ALIAS_WEIGHT)

            # From synonym -> add key
            for key, synonyms in self.aliases.items():
                if token in synonyms:
                    add_term(key, self.ALIAS_WEIGHT)

        return terms

    def get_expansion_metadata(self, terms: List[Tuple[str, float]]) -> Dict[str, Any]:
        """Get metadata about the expansion for telemetry.

        Args:
            terms: List of (term, weight) tuples from expand()

        Returns:
            Dict with expansion metadata
        """
        alias_terms = [t for t, w in terms if w == self.ALIAS_WEIGHT]

        # Find which alias keys were used
        keys_used = []
        for key, synonyms in self.aliases.items():
            for term in alias_terms:
                if term in synonyms:
                    keys_used.append(key)
                    break

        return {
            "alias_expanded": len(alias_terms) > 0,
            "alias_terms_count": len(alias_terms),
            "alias_keys_used": keys_used[:5],  # Cap at 5 for telemetry
        }

import hashlib
import json
from typing import Any


def _canonical_json(data: dict[str, Any]) -> str:
    return json.dumps(data, sort_keys=True, separators=(",", ":"), ensure_ascii=True)


def compute_projection_fingerprint(payload: dict[str, Any], policy_version: str) -> str:
    canonical = _canonical_json(payload)
    raw = f"{canonical}|{policy_version}".encode("utf-8")
    return hashlib.sha256(raw).hexdigest()

"""Obsidian note renderer with YAML frontmatter.

This module renders Finding objects as Obsidian markdown notes with
YAML frontmatter for Dataview queries and linking.

Following Trifecta Clean Architecture:
- Application layer: handles data transformation and rendering
- Uses domain models from src.domain.obsidian_models
- Pure function: no side effects, just data → string
"""

from __future__ import annotations

from datetime import datetime, timezone
from pathlib import Path
from typing import TYPE_CHECKING

from src.domain.obsidian_models import Finding, ObsidianNote

if TYPE_CHECKING:
    from collections.abc import Mapping


class NoteRenderer:
    """Render Obsidian notes from findings.

    Converts Finding objects to ObsidianNote instances with properly
    formatted YAML frontmatter and markdown body.

    Usage:
        renderer = NoteRenderer()
        note = renderer.render(finding, vault_path)
        note_content = note.render()
    """

    def __init__(self, date_format: str = "%Y-%m-%d"):
        """Initialize renderer.

        Args:
            date_format: Date format for note filenames
        """
        self.date_format = date_format

    def render(self, finding: Finding, vault_path: Path) -> ObsidianNote:
        """Render a finding as an Obsidian note.

        Args:
            finding: The finding to render
            vault_path: Path to Obsidian vault (for relative paths)

        Returns:
            ObsidianNote instance
        """
        filename = self._generate_filename(finding)
        note_path = vault_path / "Trifecta Findings" / filename

        frontmatter = self._render_frontmatter(finding)
        content = self._render_body(finding)

        return ObsidianNote(
            path=note_path,
            filename=filename,
            frontmatter=frontmatter,
            content=content,
            created=datetime.now(timezone.utc),
            finding_id=finding.id,
        )

    def _generate_filename(self, finding: Finding) -> str:
        """Generate note filename from finding.

        Format: {date}-{priority}-{id}.md
        Example: 2026-01-03-P1-violation-20260103120000.md
        """
        date_str = finding.created.strftime(self.date_format)
        # Sanitize title for filename
        return f"{date_str}-{finding.priority}-{finding.id}.md"

    def _render_frontmatter(self, finding: Finding) -> Mapping[str, object]:
        """Render YAML frontmatter from finding.

        Returns:
            Dictionary compatible with YAML dump
        """
        frontmatter: dict[str, object] = {
            "id": finding.id,
            "title": finding.title,
            "created": finding.created.isoformat(),
            "segment": finding.segment,
            "segment_id": finding.segment_id,
            "priority": finding.priority,
            "status": finding.status,
            "tags": finding.tags,
            "category": finding.category,
            "effort": finding.effort,
            "risk": finding.risk,
        }

        # Add optional fields
        if finding.roi:
            frontmatter["roi"] = finding.roi

        # Traceability
        if finding.traceability:
            trace: dict[str, str | None] = {}
            if finding.traceability.hookify_rule:
                trace["hookify_rule"] = finding.traceability.hookify_rule
            if finding.traceability.commit:
                trace["commit"] = finding.traceability.commit
            if finding.traceability.command:
                trace["command"] = finding.traceability.command
            if finding.traceability.test_command:
                trace["test_command"] = finding.traceability.test_command
            if finding.traceability.location:
                trace["location"] = finding.traceability.location
            if finding.traceability.report_path:
                trace["report_path"] = finding.traceability.report_path
            if trace:
                frontmatter["traceability"] = trace

        # Evidence
        if finding.evidence:
            evidence: dict[str, str | Mapping[str, str] | None] = {}
            if finding.evidence.pattern:
                evidence["pattern"] = finding.evidence.pattern
            if finding.evidence.context:
                evidence["context"] = finding.evidence.context
            if finding.evidence.scan_output:
                evidence["scan_output"] = finding.evidence.scan_output
            if finding.evidence.tripwire_test:
                evidence["tripwire_test"] = finding.evidence.tripwire_test
            if evidence:
                frontmatter["evidence"] = evidence

        # Metadata
        if finding.metadata:
            meta: dict[str, str | None] = {}
            if finding.metadata.pattern_family:
                meta["pattern_family"] = finding.metadata.pattern_family
            if finding.metadata.fix_lean_lines:
                meta["fix_lean_lines"] = str(finding.metadata.fix_lean_lines)
            if finding.metadata.adr:
                meta["adr"] = finding.metadata.adr
            meta["detected_at"] = finding.metadata.detected_at or finding.created.isoformat()
            meta["detected_by"] = finding.metadata.detected_by
            frontmatter["metadata"] = meta

        # Actions
        if finding.actions:
            actions_list = [
                {
                    "type": action.type,
                    "description": action.description,
                    "files": action.files,
                    "estimate": action.estimate,
                }
                for action in finding.actions
            ]
            frontmatter["actions"] = actions_list

        # Related
        if finding.related:
            related: dict[str, list[str]] = {}
            if finding.related.blocks:
                related["blocks"] = finding.related.blocks
            if finding.related.blocked_by:
                related["blocked_by"] = finding.related.blocked_by
            if finding.related.duplicates:
                related["duplicates"] = finding.related.duplicates
            if finding.related.related:
                related["related"] = finding.related.related
            if related:
                frontmatter["related"] = related

        # Links (reference strings, not wiki-links for portability)
        links: dict[str, str] = {}
        links["segment_name"] = finding.segment
        links["segment_id"] = finding.segment_id

        if finding.metadata and finding.metadata.adr:
            links["adr_reference"] = f"ADR-{finding.metadata.adr}"

        frontmatter["links"] = links

        return frontmatter

    def _render_body(self, finding: Finding) -> str:
        """Render note body content.

        Returns:
            Markdown content for the note body
        """
        lines = [
            f"# {finding.title}",
            "",
            "## Summary",
            finding.summary,
            "",
            "## Risk",
            finding.risk,
            "",
        ]

        # Pattern detected
        lines.extend(
            [
                "## Pattern Detected",
            ]
        )

        if finding.traceability and finding.traceability.hookify_rule:
            lines.append(f"**Hookify Rule**: `{finding.traceability.hookify_rule}`")

        if finding.evidence and finding.evidence.pattern:
            lines.append(f"**Pattern**: `{finding.evidence.pattern}`")

        lines.append("")

        # Evidence
        lines.extend(
            [
                "## Evidence",
            ]
        )

        if finding.evidence and finding.evidence.context:
            lines.append("**Context**:")
            lines.append("```")
            for key, value in finding.evidence.context.items():
                if value:
                    lines.append(f"{key}: {value}")
            lines.append("```")
            lines.append("")

        if finding.traceability and finding.traceability.location:
            lines.append(f"**Location**: `{finding.traceability.location}`")
            lines.append("")

        # Fix lean
        if finding.fix_lean:
            lines.extend(
                [
                    "## Fix Lean",
                    f"**Estimated Effort**: {finding.effort}",
                    "```python",
                    finding.fix_lean,
                    "```",
                    "",
                ]
            )

        # Actions
        if finding.actions:
            lines.extend(
                [
                    "## Actions",
                ]
            )
            for i, action in enumerate(finding.actions, 1):
                lines.append(f"{i}. [ ] **{action.type}**: {action.description}")
                if action.files:
                    lines.append(f"   - Files: {', '.join(action.files)}")
                lines.append(f"   - Estimate: {action.estimate}")
            lines.append("")

        # Traceability
        lines.extend(
            [
                "## Traceability",
                f"- **Detected**: {finding.created.isoformat()}",
                f"- **Source**: `{finding.metadata.detected_by if finding.metadata else 'unknown'}`",
                f"- **Segment**: `{finding.segment}` (ID: `{finding.segment_id}`)",
                f"- **Priority**: `{finding.priority}`",
                "",
            ]
        )

        # Related
        if finding.related:
            related_items: list[str] = []
            if finding.related.blocks:
                related_items.extend(f"[[{id}]]" for id in finding.related.blocks)
            if finding.related.blocked_by:
                related_items.extend(f"[[{id}]]" for id in finding.related.blocked_by)
            if finding.related.related:
                related_items.extend(f"[[{id}]]" for id in finding.related.related)

            if related_items:
                lines.extend(
                    [
                        "## Related",
                    ]
                )
                for related_id in related_items:
                    lines.append(f"- {related_id}")
                lines.append("")

        # Description (detailed)
        lines.extend(
            [
                "## Details",
                finding.description,
                "",
            ]
        )

        return "\n".join(lines)

"""Import extractor using stdlib AST."""

import ast
from src.domain.discovery_models import ImportInfo, ExtractionResult


class ImportExtractor(ast.NodeVisitor):
    """AST visitor that extracts import statements."""

    def __init__(self) -> None:
        self.imports: list[ImportInfo] = []
        self.warnings: list[str] = []

    def visit_Import(self, node: ast.Import) -> None:
        for alias in node.names:
            self.imports.append(
                ImportInfo(
                    name=alias.name,
                    is_relative=False,
                    level=0,
                    imported_names=(),
                )
            )

    def visit_ImportFrom(self, node: ast.ImportFrom) -> None:
        if node.module == "__builtins__":
            return

        imported_names = tuple(alias.name for alias in node.names)

        self.imports.append(
            ImportInfo(
                name=node.module or "",
                is_relative=node.level > 0,
                level=node.level,
                imported_names=imported_names,
            )
        )

    def visit_Call(self, node: ast.Call) -> None:
        if isinstance(node.func, ast.Name) and node.func.id == "__import__":
            self.warnings.append(f"Dynamic import detected at line {node.lineno}")
        self.generic_visit(node)


def extract_imports(source: str) -> ExtractionResult:
    """Extract import statements from Python source code.

    Args:
        source: Python source code as string.

    Returns:
        ExtractionResult containing all imports and warnings.
    """
    if not source:
        return ExtractionResult(imports=(), line_count=0, warnings=())

    try:
        tree = ast.parse(source)
    except SyntaxError:
        return ExtractionResult(imports=(), line_count=0, warnings=("Syntax error in source",))

    extractor = ImportExtractor()
    extractor.visit(tree)

    return ExtractionResult(
        imports=tuple(extractor.imports),
        line_count=len(source.splitlines()),
        warnings=tuple(extractor.warnings),
    )

"""Zero-hit ratio report generation with source segmentation.

B0 Instrumentation: Report zero-hit rates segmented by source (test/fixture/interactive/agent)
and build SHA to enable precise measurement of zero-hit reduction interventions.
"""

import json
from datetime import datetime, timedelta, timezone
from pathlib import Path
from typing import Any, Optional
from collections import defaultdict


def generate_zero_hit_report(
    segment_path: Path, days: int = 30, output_path: Optional[Path] = None
) -> str:
    """Generate zero-hit ratio report segmented by source and build.

    Args:
        segment_path: Path to segment with telemetry
        days: Number of days to look back
        output_path: Optional path to write report

    Returns:
        Markdown formatted report
    """
    events_path = segment_path / "_ctx" / "telemetry" / "events.jsonl"

    if not events_path.exists():
        return "# Zero-Hit Report\n\nNo telemetry data found."

    # Parse events
    events = []
    with open(events_path) as f:
        for line in f:
            if line.strip():
                try:
                    events.append(json.loads(line))
                except json.JSONDecodeError:
                    continue

    # Filter to ctx.search events within time window
    from datetime import timezone

    cutoff = datetime.now(timezone.utc) - timedelta(days=days)

    def parse_ts(ts_str):
        """Parse timestamp string, handling both offset-aware and naive."""
        if not ts_str:
            return datetime(2000, 1, 1, tzinfo=timezone.utc)
        # Handle Z suffix (UTC)
        if ts_str.endswith("Z"):
            ts_str = ts_str[:-1] + "+00:00"
        try:
            dt = datetime.fromisoformat(ts_str)
            # If naive, assume UTC
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=timezone.utc)
            return dt
        except ValueError:
            return datetime(2000, 1, 1, tzinfo=timezone.utc)

    search_events = [
        e for e in events if e.get("cmd") == "ctx.search" and parse_ts(e.get("ts")) > cutoff
    ]

    # Aggregate by source
    by_source = defaultdict(lambda: {"total": 0, "zero_hits": 0, "reasons": defaultdict(int)})
    by_build = defaultdict(lambda: {"total": 0, "zero_hits": 0})

    for event in search_events:
        # Get source from extended fields (x) or default to "unknown"
        x = event.get("x", {})
        source = x.get("source", "unknown")
        build_sha = x.get("build_sha", "unknown")

        hits = event.get("result", {}).get("hits", 0)

        by_source[source]["total"] += 1
        by_build[build_sha]["total"] += 1

        if hits == 0:
            by_source[source]["zero_hits"] += 1
            by_build[build_sha]["zero_hits"] += 1

            # Track zero-hit reason
            reason = x.get("zero_hit_reason", "unknown")
            by_source[source]["reasons"][reason] += 1

    # Generate report
    lines = [
        "# Zero-Hit Ratio Report",
        f"\nGenerated: {datetime.now().isoformat()}",
        f"Period: Last {days} days",
        f"Total searches: {len(search_events)}\n",
        "## By Source",
        "",
        "| Source | Total | Zero Hits | Ratio |",
        "|--------|-------|-----------|-------|",
    ]

    for source in sorted(by_source.keys()):
        data = by_source[source]
        ratio = (data["zero_hits"] / data["total"] * 100) if data["total"] > 0 else 0
        lines.append(f"| {source} | {data['total']} | {data['zero_hits']} | {ratio:.1f}% |")

    lines.extend(
        [
            "",
            "## Zero-Hit Reasons by Source",
            "",
        ]
    )

    for source in sorted(by_source.keys()):
        data = by_source[source]
        if data["reasons"]:
            lines.append(f"### {source}")
            lines.append("")
            lines.append("| Reason | Count | % of Zero Hits |")
            lines.append("|--------|-------|----------------|")

            total_zero = data["zero_hits"]
            for reason, count in sorted(data["reasons"].items(), key=lambda x: -x[1]):
                pct = (count / total_zero * 100) if total_zero > 0 else 0
                lines.append(f"| {reason} | {count} | {pct:.1f}% |")
            lines.append("")

    lines.extend(
        [
            "## By Build",
            "",
            "| Build SHA | Total | Zero Hits | Ratio |",
            "|-----------|-------|-----------|-------|",
        ]
    )

    # Sort by most recent builds (assuming SHA order correlates with time)
    for build_sha in sorted(by_build.keys(), reverse=True)[:10]:
        data = by_build[build_sha]
        ratio = (data["zero_hits"] / data["total"] * 100) if data["total"] > 0 else 0
        lines.append(f"| {build_sha} | {data['total']} | {data['zero_hits']} | {ratio:.1f}% |")

    report = "\n".join(lines)

    if output_path:
        output_path.write_text(report)

    return report


def get_zero_hit_metrics(segment_path: Path, days: int = 30) -> dict[str, Any]:
    """Get zero-hit metrics as dictionary for programmatic use.

    Args:
        segment_path: Path to segment with telemetry
        days: Number of days to look back

    Returns:
        Dictionary with metrics by source and overall
    """
    events_path = segment_path / "_ctx" / "telemetry" / "events.jsonl"

    if not events_path.exists():
        return {"error": "No telemetry data"}

    events = []
    with open(events_path) as f:
        for line in f:
            if line.strip():
                try:
                    events.append(json.loads(line))
                except json.JSONDecodeError:
                    continue

    cutoff = datetime.now(timezone.utc) - timedelta(days=days)

    def parse_ts(ts_str):
        if not ts_str:
            return datetime(2000, 1, 1, tzinfo=timezone.utc)
        if ts_str.endswith("Z"):
            ts_str = ts_str[:-1] + "+00:00"
        try:
            dt = datetime.fromisoformat(ts_str)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=timezone.utc)
            return dt
        except ValueError:
            return datetime(2000, 1, 1, tzinfo=timezone.utc)

    search_events = [
        e for e in events if e.get("cmd") == "ctx.search" and parse_ts(e.get("ts")) > cutoff
    ]

    by_source = defaultdict(lambda: {"total": 0, "zero_hits": 0})

    for event in search_events:
        x = event.get("x", {})
        source = x.get("source", "unknown")
        hits = event.get("result", {}).get("hits", 0)

        by_source[source]["total"] += 1
        if hits == 0:
            by_source[source]["zero_hits"] += 1

    total = len(search_events)
    total_zero = sum(s["zero_hits"] for s in by_source.values())
    overall_ratio = (total_zero / total * 100) if total > 0 else 0

    return {
        "period_days": days,
        "total_searches": total,
        "total_zero_hits": total_zero,
        "overall_ratio": round(overall_ratio, 2),
        "by_source": {
            source: {
                "total": data["total"],
                "zero_hits": data["zero_hits"],
                "ratio": round(data["zero_hits"] / data["total"] * 100, 2)
                if data["total"] > 0
                else 0,
            }
            for source, data in by_source.items()
        },
    }


if __name__ == "__main__":
    import sys

    if len(sys.argv) > 1:
        segment = Path(sys.argv[1])
    else:
        segment = Path(".")

    report = generate_zero_hit_report(segment)
    print(report)

import ast as ast_module
from dataclasses import dataclass
from datetime import datetime, timezone
from pathlib import Path

from src.application.ast_parser import SkeletonMapBuilder
from src.domain.graph_models import (
    GraphEdge,
    GraphIndexSummary,
    GraphNode,
    make_edge_id,
    make_node_id,
)
from src.domain.segment_resolver import resolve_segment_ref
from src.infrastructure.graph_store import GraphStore


@dataclass(frozen=True)
class _FileGraphData:
    nodes: list[GraphNode]
    edges: list[GraphEdge]


class _DirectCallCollector(ast_module.NodeVisitor):
    def __init__(self) -> None:
        self.call_names: list[str] = []

    def visit_Call(self, node: ast_module.Call) -> None:
        if isinstance(node.func, ast_module.Name):
            self.call_names.append(node.func.id)
        return None

    def visit_FunctionDef(self, node: ast_module.FunctionDef) -> None:
        return None

    def visit_AsyncFunctionDef(self, node: ast_module.AsyncFunctionDef) -> None:
        return None

    def visit_ClassDef(self, node: ast_module.ClassDef) -> None:
        return None

    def visit_Lambda(self, node: ast_module.Lambda) -> None:
        return None


class GraphIndexer:
    def __init__(self, store: GraphStore | None = None) -> None:
        self._store = store

    def index_segment(self, segment: Path | str) -> GraphIndexSummary:
        segment_ref = resolve_segment_ref(segment)
        segment_root = segment_ref.root_abs
        store = self._store or GraphStore(
            GraphStore.db_path_for_segment(segment_root, segment_ref.id),
            segment_id=segment_ref.id,
        )
        builder = SkeletonMapBuilder(segment_id=str(segment_root))
        indexed_at = datetime.now(timezone.utc).isoformat()

        all_nodes: list[GraphNode] = []
        all_edges: list[GraphEdge] = []
        source_root = segment_root / "src"

        if source_root.exists():
            for file_path in sorted(source_root.rglob("*.py")):
                file_data = self._index_file(segment_ref.id, segment_root, file_path, builder)
                all_nodes.extend(file_data.nodes)
                all_edges.extend(file_data.edges)

        store.replace_segment(segment_ref.id, all_nodes, all_edges, indexed_at=indexed_at)
        return GraphIndexSummary(
            segment_id=segment_ref.id,
            db_path=str(store.db_path),
            node_count=len(all_nodes),
            edge_count=len(all_edges),
            indexed_at=indexed_at,
        )

    def _index_file(
        self,
        segment_id: str,
        segment_root: Path,
        file_path: Path,
        builder: SkeletonMapBuilder,
    ) -> _FileGraphData:
        parse_result = builder.build(file_path)
        file_rel = str(file_path.relative_to(segment_root))
        nodes = [
            GraphNode(
                id=make_node_id(segment_id, file_rel, symbol.qualified_name),
                segment_id=segment_id,
                file_rel=file_rel,
                symbol_name=symbol.name,
                qualified_name=symbol.qualified_name,
                kind=symbol.kind,
                line=symbol.start_line,
                metadata_json=None,
            )
            for symbol in parse_result.symbols
        ]

        edges = self._extract_edges(segment_id, file_path, nodes)
        return _FileGraphData(nodes=nodes, edges=edges)

    def _extract_edges(
        self,
        segment_id: str,
        file_path: Path,
        nodes: list[GraphNode],
    ) -> list[GraphEdge]:
        content = file_path.read_text(errors="replace")
        try:
            tree = ast_module.parse(content, filename=str(file_path))
        except SyntaxError:
            return []

        caller_ids = {node.symbol_name: node.id for node in nodes if node.kind == "function"}
        call_target_ids = {
            node.symbol_name: node.id for node in nodes if node.kind in {"function", "class"}
        }
        edges: list[GraphEdge] = []

        for node in tree.body:
            if not isinstance(node, (ast_module.FunctionDef, ast_module.AsyncFunctionDef)):
                continue
            caller_id = caller_ids.get(node.name)
            if caller_id is None:
                continue
            collector = _DirectCallCollector()
            for statement in node.body:
                collector.visit(statement)
            for callee_name in collector.call_names:
                callee_id = call_target_ids.get(callee_name)
                if callee_id is None or callee_id == caller_id:
                    continue
                edge_id = make_edge_id(segment_id, caller_id, callee_id, "calls")
                edges.append(
                    GraphEdge(
                        id=edge_id,
                        segment_id=segment_id,
                        from_node_id=caller_id,
                        to_node_id=callee_id,
                        edge_kind="calls",
                        source="ast",
                        confidence=1.0,
                    )
                )

        deduped: dict[str, GraphEdge] = {edge.id: edge for edge in edges}
        return list(deduped.values())

from __future__ import annotations

import json
from dataclasses import dataclass
from datetime import datetime, timezone
from pathlib import Path
from typing import Any

import yaml

from src.application.linear_fingerprint import compute_projection_fingerprint
from src.application.linear_journal import append_journal_event, load_or_rebuild_state, write_state_snapshot
from src.application.linear_mapper import build_linear_payload
from src.application.linear_reconcile import classify_drift, diff_payload, write_reconcile_reports
from src.domain.linear_models import REQUIRED_TRIFECTA_STATUSES, LinearPolicy
from src.domain.linear_policy import load_linear_policy
from src.infrastructure.linear_mcp_client import (
    LinearMCPCapabilityError,
    LinearMCPClient,
    LinearMCPError,
)


RECONCILE_EXIT_OK = 0
RECONCILE_EXIT_WARN = 2
RECONCILE_EXIT_FATAL = 3
RECONCILE_EXIT_TECH = 1

SYNC_EXIT_OK = 0
SYNC_EXIT_FATAL = 3
SYNC_EXIT_TECH = 1

BOOTSTRAP_EXIT_OK = 0
BOOTSTRAP_EXIT_TECH = 1


@dataclass
class LinearActionResult:
    ok: bool
    fatal: bool = False
    warn: bool = False
    message: str = ""
    exit_code: int = 0


class LinearSyncUseCase:
    def __init__(self, root: Path, mcp_client: LinearMCPClient | None = None):
        self.root = root.resolve()
        self.policy_path = self.root / "_ctx" / "policy" / "linear_sync_policy.yaml"
        self.status_map_path = self.root / "_ctx" / "linear_sync" / "status_map.json"
        self.policy: LinearPolicy = load_linear_policy(self.policy_path)
        self.client = mcp_client or LinearMCPClient()

    def _load_status_map_cache(self) -> dict[str, Any] | None:
        if not self.status_map_path.exists():
            return None
        try:
            data = json.loads(self.status_map_path.read_text(encoding="utf-8"))
        except json.JSONDecodeError:
            return None
        if not isinstance(data, dict):
            return None

        if data.get("policy_version") != self.policy.policy_version:
            return None

        team_id = str(data.get("team_id") or "").strip()
        if self.policy.team_id and team_id != self.policy.team_id:
            return None

        status_map = data.get("status_map")
        if not isinstance(status_map, dict):
            return None
        if any(not isinstance(status_map.get(s), str) or not status_map.get(s) for s in REQUIRED_TRIFECTA_STATUSES):
            return None
        return data

    def _save_status_map_cache(
        self,
        team_id: str,
        status_map: dict[str, str],
        linear_state_id_to_name: dict[str, str],
    ) -> None:
        self.status_map_path.parent.mkdir(parents=True, exist_ok=True)
        data = {
            "team_id": team_id,
            "policy_version": self.policy.policy_version,
            "generated_at": datetime.now(timezone.utc).isoformat(),
            "status_map": status_map,
            "linear_state_id_to_name": linear_state_id_to_name,
        }
        self.status_map_path.write_text(
            json.dumps(data, indent=2, sort_keys=True) + "\n", encoding="utf-8"
        )

    def bootstrap(self) -> LinearActionResult:
        try:
            self.client.check_capabilities()
            cached = self._load_status_map_cache()
            if cached:
                return LinearActionResult(ok=True, exit_code=BOOTSTRAP_EXIT_OK, message="status_map cache valid")

            team_id = self.policy.team_id
            if not team_id:
                resolved = self.client.resolve_team(self.policy.team_key)
                team_id = str(resolved.get("team_id") or "").strip()
            if not team_id:
                raise LinearMCPError("Unable to resolve Linear team_id")

            states_resp = self.client.list_workflow_states(team_id)
            states = states_resp.get("states")
            if not isinstance(states, list):
                raise LinearMCPError("list_workflow_states returned invalid payload")

            by_name: dict[str, str] = {}
            id_to_name: dict[str, str] = {}
            for item in states:
                if not isinstance(item, dict):
                    continue
                name = str(item.get("name") or "").strip()
                state_id = str(item.get("id") or "").strip()
                if name and state_id:
                    by_name[name.lower()] = state_id
                    id_to_name[state_id] = name

            name_candidates = {
                "pending": ["todo", "backlog", "pending"],
                "running": ["in progress", "started"],
                "partial": ["in progress", "started"],
                "done": ["done", "completed"],
                "failed": ["canceled", "cancelled", "failed"],
            }
            resolved_map: dict[str, str] = {}
            for key, names in name_candidates.items():
                state_id = next((by_name[n] for n in names if n in by_name), "")
                if not state_id:
                    raise LinearMCPError(f"Missing required workflow state for '{key}'")
                resolved_map[key] = state_id

            self._save_status_map_cache(team_id=team_id, status_map=resolved_map, linear_state_id_to_name=id_to_name)
            return LinearActionResult(ok=True, exit_code=BOOTSTRAP_EXIT_OK)
        except (LinearMCPError, LinearMCPCapabilityError) as exc:
            return LinearActionResult(ok=False, exit_code=BOOTSTRAP_EXIT_TECH, message=str(exc))

    def doctor(self) -> LinearActionResult:
        """Run fail-closed diagnostics for viewer mode setup."""
        try:
            self.client.check_capabilities()
            cached = self._load_status_map_cache()
            if not cached:
                return LinearActionResult(
                    ok=False,
                    exit_code=BOOTSTRAP_EXIT_TECH,
                    message="status_map cache missing or invalid; run linear bootstrap",
                )
            return LinearActionResult(ok=True, exit_code=BOOTSTRAP_EXIT_OK, message="doctor ok")
        except (LinearMCPError, LinearMCPCapabilityError) as exc:
            return LinearActionResult(ok=False, exit_code=BOOTSTRAP_EXIT_TECH, message=str(exc))

    def _load_work_orders(self) -> list[tuple[dict[str, Any], Path]]:
        out: list[tuple[dict[str, Any], Path]] = []
        for state in ("pending", "running", "done", "failed"):
            state_dir = self.root / "_ctx" / "jobs" / state
            if not state_dir.exists():
                continue
            for wo_file in sorted(state_dir.glob("WO-*.yaml")):
                loaded = yaml.safe_load(wo_file.read_text(encoding="utf-8"))
                if isinstance(loaded, dict):
                    out.append((loaded, wo_file))
        return out

    def _status_map(self) -> dict[str, str]:
        cached = self._load_status_map_cache()
        if not cached:
            raise LinearMCPError("status_map cache missing or invalid; run linear bootstrap")
        return cached["status_map"]

    @staticmethod
    def _normalize_issue_for_diff(
        current: dict[str, Any],
        projected: dict[str, Any],
        linear_state_id_to_name: dict[str, str] | None = None,
    ) -> dict[str, Any]:
        normalized: dict[str, Any] = {}
        name_to_state_id: dict[str, str] = {}
        if isinstance(linear_state_id_to_name, dict):
            for sid, sname in linear_state_id_to_name.items():
                if isinstance(sid, str) and isinstance(sname, str):
                    name_to_state_id[sname.strip().lower()] = sid

        for key in projected.keys():
            value = current.get(key)
            if key == "state":
                if isinstance(value, dict):
                    value = value.get("id") or value.get("stateId") or value.get("name")
                if not value:
                    value = current.get("status")
                if isinstance(value, str):
                    lowered = value.strip().lower()
                    value = name_to_state_id.get(lowered, value)
            elif key == "priority" and isinstance(value, dict):
                value = value.get("value")
            elif key == "labels":
                if isinstance(value, list):
                    labels: list[str] = []
                    for item in value:
                        if isinstance(item, str):
                            labels.append(item)
                        elif isinstance(item, dict) and isinstance(item.get("name"), str):
                            labels.append(item["name"])
                    value = sorted(set(labels))
            elif key == "team":
                if isinstance(value, dict):
                    value = value.get("id") or value.get("key") or value.get("name")
                if current.get("teamId"):
                    value = current.get("teamId")
                elif not value:
                    value = current.get("team")
            elif key == "project":
                if isinstance(value, dict):
                    value = value.get("id") or value.get("name")
            elif key == "assignee" and isinstance(value, dict):
                value = value.get("id") or value.get("email") or value.get("name")

            normalized[key] = value
        return normalized

    def push_wo(self, wo_id: str) -> LinearActionResult:
        try:
            status_map = self._status_map()
            cache = self._load_status_map_cache() or {}
            resolved_team_id = str(cache.get("team_id") or "").strip()
            state = load_or_rebuild_state(self.root)
            wo_pair = next(((wo, path) for wo, path in self._load_work_orders() if wo.get("id") == wo_id), None)
            if wo_pair is None:
                raise LinearMCPError(f"WO not found: {wo_id}")
            wo, wo_path = wo_pair
            trifecta_status = str(wo.get("status") or "pending")
            linear_state_id = status_map.get(trifecta_status)
            if not linear_state_id:
                raise LinearMCPError(f"No status map for WO status '{trifecta_status}'")

            payload = build_linear_payload(wo, self.policy, linear_state_id, wo_path)
            if resolved_team_id:
                payload["team"] = resolved_team_id
            fingerprint = compute_projection_fingerprint(payload, self.policy.policy_version)
            comparable_keys = set(self.policy.outbound_allow) | {"team"}
            comparable_payload = {k: v for k, v in payload.items() if k in comparable_keys}

            entry = state.get(wo_id)
            if isinstance(entry, dict):
                issue_id = str(entry.get("linear_issue_id") or "")
            else:
                issue_id = ""

            if not issue_id:
                issues = self.client.list_issues(resolved_team_id or self.policy.team_id or self.policy.team_key)
                for issue in issues.get("issues", []):
                    if not isinstance(issue, dict):
                        continue
                    by_anchor = issue.get("wo_id") == wo_id
                    title = str(issue.get("title") or "")
                    by_title = title.startswith(f"[{wo_id}]")
                    if by_anchor or by_title:
                        issue_id = str(issue.get("id") or "")
                        if issue_id:
                            break

            if not issue_id:
                created = self.client.create_issue(payload)
                issue = created.get("issue") if isinstance(created, dict) else None
                issue_id = str((issue or {}).get("id") or "")
                if not issue_id and isinstance(created, dict):
                    issue_id = str(created.get("id") or "")
                if not issue_id:
                    raise LinearMCPError("create_issue did not return issue id")
                action = "create"
            else:
                current_resp = self.client.get_issue(issue_id)
                current = current_resp.get("issue") or {}
                current_norm = self._normalize_issue_for_diff(
                    current,
                    comparable_payload,
                    (cache.get("linear_state_id_to_name") if isinstance(cache, dict) else None),
                )
                diffs = diff_payload(comparable_payload, current_norm)
                changed_fields = set(diffs.keys())
                if not changed_fields and isinstance(entry, dict):
                    if str(entry.get("last_fingerprint") or "") == fingerprint:
                        return LinearActionResult(ok=True, exit_code=SYNC_EXIT_OK, message="noop")
                if changed_fields:
                    severity = classify_drift(changed_fields, self.policy)
                    if severity == "FATAL":
                        append_journal_event(
                            self.root,
                            {
                                "op": "push",
                                "wo_id": wo_id,
                                "linear_issue_id": issue_id,
                                "last_fingerprint": str(entry.get("last_fingerprint") if isinstance(entry, dict) else ""),
                                "policy_version": self.policy.policy_version,
                                "updated_at": datetime.now(timezone.utc).isoformat(),
                                "severity": "FATAL",
                                "changed_fields": sorted(changed_fields),
                            },
                        )
                        return LinearActionResult(ok=False, fatal=True, exit_code=SYNC_EXIT_FATAL, message="fatal drift")
                self.client.update_issue(issue_id, payload)
                action = "update"

            if "state" in payload:
                self.client.transition_issue_state(issue_id, linear_state_id)
            if "labels" in payload:
                labels = payload.get("labels")
                if isinstance(labels, list):
                    self.client.set_labels(issue_id, labels)

            append_journal_event(
                self.root,
                {
                    "op": action,
                    "wo_id": wo_id,
                    "linear_issue_id": issue_id,
                    "last_fingerprint": fingerprint,
                    "policy_version": self.policy.policy_version,
                    "updated_at": datetime.now(timezone.utc).isoformat(),
                },
            )
            state[wo_id] = {
                "linear_issue_id": issue_id,
                "last_fingerprint": fingerprint,
                "policy_version": self.policy.policy_version,
                "updated_at": datetime.now(timezone.utc).isoformat(),
            }
            write_state_snapshot(self.root, state)
            return LinearActionResult(ok=True, exit_code=SYNC_EXIT_OK, message=action)
        except LinearMCPError as exc:
            return LinearActionResult(ok=False, exit_code=SYNC_EXIT_TECH, message=str(exc))

    def sync(self) -> LinearActionResult:
        fatal_count = 0
        for wo, _ in self._load_work_orders():
            wo_id = str(wo.get("id") or "")
            if not wo_id:
                continue
            res = self.push_wo(wo_id)
            if res.exit_code == SYNC_EXIT_TECH:
                return res
            if res.fatal:
                fatal_count += 1

        if fatal_count > 0:
            return LinearActionResult(ok=False, fatal=True, exit_code=SYNC_EXIT_FATAL, message=f"fatal_count={fatal_count}")
        return LinearActionResult(ok=True, exit_code=SYNC_EXIT_OK)

    def reconcile(self, dry_run: bool = True) -> LinearActionResult:
        try:
            status_map = self._status_map()
            findings: list[dict[str, Any]] = []
            max_sev = "INFO"

            state = load_or_rebuild_state(self.root)
            for wo, wo_path in self._load_work_orders():
                wo_id = str(wo.get("id") or "")
                entry = state.get(wo_id)
                if not isinstance(entry, dict):
                    continue
                issue_id = str(entry.get("linear_issue_id") or "")
                if not issue_id:
                    continue
                linear_state_id = status_map.get(str(wo.get("status") or "pending"))
                if not linear_state_id:
                    continue

                payload = build_linear_payload(wo, self.policy, linear_state_id, wo_path)
                comparable_keys = set(self.policy.outbound_allow) | {"team"}
                comparable_payload = {k: v for k, v in payload.items() if k in comparable_keys}
                current_resp = self.client.get_issue(issue_id)
                current = current_resp.get("issue") or {}
                if not isinstance(current, dict):
                    continue
                current_norm = self._normalize_issue_for_diff(
                    current,
                    comparable_payload,
                    (self._load_status_map_cache() or {}).get("linear_state_id_to_name"),
                )
                diffs = diff_payload(comparable_payload, current_norm)
                if not diffs:
                    continue
                changed_fields = set(diffs.keys())
                sev = classify_drift(changed_fields, self.policy)
                if sev == "FATAL":
                    max_sev = "FATAL"
                elif sev == "WARN" and max_sev != "FATAL":
                    max_sev = "WARN"

                findings.append(
                    {
                        "wo_id": wo_id,
                        "linear_issue_id": issue_id,
                        "severity": sev,
                        "changed_fields": sorted(changed_fields),
                        "dry_run": dry_run,
                    }
                )

            write_reconcile_reports(self.root, findings, self.policy.policy_version)

            if max_sev == "FATAL":
                return LinearActionResult(ok=False, fatal=True, exit_code=RECONCILE_EXIT_FATAL)
            if max_sev == "WARN":
                return LinearActionResult(ok=True, warn=True, exit_code=RECONCILE_EXIT_WARN)
            return LinearActionResult(ok=True, exit_code=RECONCILE_EXIT_OK)
        except LinearMCPError as exc:
            return LinearActionResult(ok=False, exit_code=RECONCILE_EXIT_TECH, message=str(exc))

"""Load YAML configs with graceful error handling and auditable markers."""

import sys
from pathlib import Path
from typing import Dict, Any
import yaml


class ConfigLoader:
    """Load YAML configs from repo root configs/ directory.

    Returns auditable markers when configs are missing or invalid.
    """

    @staticmethod
    def load_anchors(repo_root: Path) -> Dict[str, Any]:
        """Load anchors.yaml from repo root configs/.

        Returns:
            - Dict with anchors data if valid
            - {"_missing_config": True, "anchors": {}} if missing or invalid

        Graceful degradation: never raises, always returns valid dict.
        Logs warnings to stderr for visibility while maintaining graceful degradation.
        """
        anchors_path = repo_root / "configs" / "anchors.yaml"

        if not anchors_path.exists():
            sys.stderr.write(f"[ConfigLoader] anchors.yaml not found at {anchors_path}\n")
            return {"_missing_config": True, "anchors": {}}

        try:
            with open(anchors_path, "r", encoding="utf-8") as f:
                data = yaml.safe_load(f)

                if not isinstance(data, dict) or "anchors" not in data:
                    sys.stderr.write(
                        "[ConfigLoader] anchors.yaml invalid structure (missing 'anchors' key)\n"
                    )
                    return {"_missing_config": True, "anchors": {}}

                return data

        except yaml.YAMLError as e:
            sys.stderr.write(f"[ConfigLoader] anchors.yaml YAML parse error: {e}\n")
            return {"_missing_config": True, "anchors": {}}
        except (IOError, OSError) as e:
            sys.stderr.write(f"[ConfigLoader] anchors.yaml read error: {e}\n")
            return {"_missing_config": True, "anchors": {}}

    @staticmethod
    def load_linter_aliases(repo_root: Path) -> Dict[str, Any]:
        """Load aliases.yaml from repo root configs/.

        Returns:
            - Dict with aliases data if valid
            - {"_missing_config": True, "aliases": []} if missing or invalid

        Graceful degradation: never raises, always returns valid dict.
        Logs warnings to stderr for visibility while maintaining graceful degradation.
        """
        aliases_path = repo_root / "configs" / "aliases.yaml"

        if not aliases_path.exists():
            sys.stderr.write(f"[ConfigLoader] aliases.yaml not found at {aliases_path}\n")
            return {"_missing_config": True, "aliases": []}

        try:
            with open(aliases_path, "r", encoding="utf-8") as f:
                data = yaml.safe_load(f)

                if not isinstance(data, dict) or "aliases" not in data:
                    sys.stderr.write(
                        "[ConfigLoader] aliases.yaml invalid structure (missing 'aliases' key)\n"
                    )
                    return {"_missing_config": True, "aliases": []}

                return data

        except yaml.YAMLError as e:
            sys.stderr.write(f"[ConfigLoader] aliases.yaml YAML parse error: {e}\n")
            return {"_missing_config": True, "aliases": []}
        except (IOError, OSError) as e:
            sys.stderr.write(f"[ConfigLoader] aliases.yaml read error: {e}\n")
            return {"_missing_config": True, "aliases": []}

from __future__ import annotations

import json
import os
import queue
import random
import shlex
import subprocess
import sys
import threading
import time
from dataclasses import dataclass
from typing import Any


MAX_MCP_TEXT_BYTES = 256 * 1024

REQUIRED_LINEAR_OPS: dict[str, tuple[str, ...]] = {
    "create_issue": ("create_issue",),
    "update_issue": ("update_issue",),
    "get_issue": ("get_issue",),
    "list_issues": ("list_issues",),
    "add_comment": ("add_comment", "create_comment"),
    "set_labels": ("set_labels", "update_issue"),
    "transition_issue_state": ("transition_issue_state", "update_issue"),
    "resolve_team": ("resolve_team", "list_teams", "get_team"),
    "list_workflow_states": ("list_workflow_states", "list_issue_statuses"),
}


class LinearMCPError(RuntimeError):
    pass


class LinearMCPCapabilityError(LinearMCPError):
    pass


class LinearMCPRateLimitError(LinearMCPError):
    def __init__(self, message: str, retry_ms: int = 0):
        super().__init__(message)
        self.retry_ms = retry_ms


@dataclass
class MCPResponse:
    payload: dict[str, Any]


class LinearMCPClient:
    def __init__(self, command: str | None = None) -> None:
        self.command = command or os.environ.get("LINEAR_MCP_CMD", "").strip()
        if not self.command:
            raise LinearMCPError(
                "LINEAR_MCP_CMD is required (example: 'python -m tests.fixtures.linear_mcp_fake')"
            )
        self.timeout_ms = int(os.environ.get("LINEAR_MCP_TIMEOUT_MS", "5000"))
        self.debug = os.environ.get("LINEAR_MCP_DEBUG", "0") == "1"
        self._request_id = 0
        self._lock = threading.Lock()
        self._queue: queue.Queue[dict[str, Any]] = queue.Queue()
        self._proc: subprocess.Popen[str] | None = None
        self._reader_thread: threading.Thread | None = None
        self._tool_map: dict[str, str] = {}
        self._tool_names: set[str] = set()

    def _log(self, direction: str, frame: str) -> None:
        if self.debug:
            redacted = frame.replace(os.environ.get("LINEAR_TOKEN", ""), "***")
            sys.stderr.write(f"[linear-mcp:{direction}] {redacted}\n")

    def _ensure_proc(self) -> None:
        if self._proc and self._proc.poll() is None:
            return

        self._proc = subprocess.Popen(
            shlex.split(self.command),
            stdin=subprocess.PIPE,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            text=True,
            bufsize=1,
        )

        def _reader() -> None:
            assert self._proc is not None and self._proc.stdout is not None
            for raw in self._proc.stdout:
                line = raw.strip()
                if not line:
                    continue
                self._log("in", line)
                try:
                    self._queue.put(json.loads(line))
                except json.JSONDecodeError:
                    self._queue.put({"jsonrpc": "2.0", "id": None, "error": {"code": "INVALID_JSON", "message": line}})

        self._reader_thread = threading.Thread(target=_reader, daemon=True)
        self._reader_thread.start()

    def close(self) -> None:
        if not self._proc:
            return
        try:
            if self._proc.stdin:
                self._proc.stdin.close()
        except OSError:
            pass
        self._proc.terminate()
        self._proc = None

    def __enter__(self) -> "LinearMCPClient":
        self._ensure_proc()
        return self

    def __exit__(self, exc_type, exc, tb) -> None:
        self.close()

    def _request(self, method: str, params: dict[str, Any]) -> MCPResponse:
        # single in-flight request by lock: no pipelining
        with self._lock:
            self._ensure_proc()
            if not self._proc or not self._proc.stdin:
                raise LinearMCPError("MCP process unavailable")

            self._request_id += 1
            req_id = self._request_id
            req = {
                "jsonrpc": "2.0",
                "id": req_id,
                "method": method,
                "params": params,
            }
            line = json.dumps(req, separators=(",", ":"), sort_keys=True)
            self._log("out", line)
            self._proc.stdin.write(line + "\n")
            self._proc.stdin.flush()

            try:
                response = self._queue.get(timeout=self.timeout_ms / 1000)
            except queue.Empty as exc:
                raise LinearMCPError(f"MCP request timeout after {self.timeout_ms}ms ({method})") from exc

            if response.get("id") != req_id:
                raise LinearMCPError(f"MCP protocol mismatch: expected id={req_id}, got={response.get('id')}")

            if "error" in response:
                err = response["error"]
                code = err.get("code", "UNKNOWN")
                msg = err.get("message", "MCP error")
                if code == "RATE_LIMITED":
                    retry_ms = int((err.get("data") or {}).get("retry_ms", 0))
                    raise LinearMCPRateLimitError(msg, retry_ms=retry_ms)
                raise LinearMCPError(f"MCP error {code}: {msg}")

            return MCPResponse(payload=response.get("result", {}))

    def tools_list(self) -> list[dict[str, Any]]:
        result = self._request("tools/list", {}).payload
        tools = result.get("tools", result)
        if not isinstance(tools, list):
            raise LinearMCPError("tools/list returned invalid payload")
        return [t for t in tools if isinstance(t, dict)]

    def check_capabilities(self) -> None:
        names = {t.get("name") for t in self.tools_list() if isinstance(t.get("name"), str)}
        self._tool_names = set(names)
        resolved: dict[str, str] = {}
        missing: list[str] = []
        for op in REQUIRED_LINEAR_OPS:
            selected = self._resolve_capability_tool(op, names)
            if selected:
                resolved[op] = selected
            else:
                missing.append(f"{op}({','.join(REQUIRED_LINEAR_OPS[op])})")
        if missing:
            raise LinearMCPCapabilityError(
                "MCP server missing required operations: " + ", ".join(missing)
            )
        self._tool_map = resolved
        if self.debug:
            self._log("cap", f"capability_map={json.dumps(self._tool_map, sort_keys=True)}")

    @staticmethod
    def _resolve_capability_tool(capability: str, available_tools: set[str]) -> str:
        candidates = REQUIRED_LINEAR_OPS.get(capability, ())
        for tool in candidates:
            if tool in available_tools:
                return tool
        return ""

    def _ensure_capabilities(self) -> None:
        if not self._tool_map:
            self.check_capabilities()

    def _tool_for(self, op: str) -> str:
        self._ensure_capabilities()
        tool = self._tool_map.get(op, "")
        if not tool:
            raise LinearMCPCapabilityError(f"Missing mapped tool for operation: {op}")
        return tool

    @staticmethod
    def _decode_content_payload(payload: dict[str, Any]) -> dict[str, Any]:
        if payload.get("isError") is True:
            content = payload.get("content")
            if isinstance(content, list):
                for item in content:
                    if not isinstance(item, dict):
                        continue
                    if item.get("type") != "text":
                        continue
                    text = item.get("text")
                    if isinstance(text, str) and text.strip():
                        raise LinearMCPError(f"MCP tool error: {text.strip()}")
            raise LinearMCPError("MCP tool returned error content")

        content = payload.get("content")
        if not isinstance(content, list):
            return payload
        saw_text = False
        for item in content:
            if not isinstance(item, dict):
                continue
            if item.get("type") != "text":
                continue
            saw_text = True
            text = item.get("text")
            if not isinstance(text, str) or not text.strip():
                raise LinearMCPError("MCP content.text is empty or invalid")
            if len(text.encode("utf-8")) > MAX_MCP_TEXT_BYTES:
                raise LinearMCPError(
                    f"MCP content.text exceeds max size ({MAX_MCP_TEXT_BYTES} bytes)"
                )
            try:
                parsed = json.loads(text)
            except json.JSONDecodeError:
                raise LinearMCPError("MCP content.text is not valid JSON")
            if isinstance(parsed, dict):
                return parsed
            if isinstance(parsed, list):
                return {"items": parsed}
            raise LinearMCPError("MCP content.text JSON must be object or array")
        if saw_text:
            raise LinearMCPError("MCP content.text could not be decoded")
        raise LinearMCPError("MCP content has no text item")

    @staticmethod
    def _team_candidates(payload: dict[str, Any]) -> list[dict[str, Any]]:
        teams = payload.get("teams")
        if isinstance(teams, list):
            return [x for x in teams if isinstance(x, dict)]
        items = payload.get("items")
        if isinstance(items, list):
            return [x for x in items if isinstance(x, dict)]
        team = payload.get("team")
        if isinstance(team, dict):
            return [team]
        return []

    @staticmethod
    def _status_candidates(payload: dict[str, Any]) -> list[dict[str, Any]]:
        states = payload.get("states")
        if isinstance(states, list):
            return [x for x in states if isinstance(x, dict)]
        items = payload.get("items")
        if isinstance(items, list):
            return [x for x in items if isinstance(x, dict)]
        return []

    def call_tool(self, name: str, arguments: dict[str, Any], retries: int = 3) -> dict[str, Any]:
        for attempt in range(1, retries + 1):
            try:
                res = self._request("tools/call", {"name": name, "arguments": arguments}).payload
                if isinstance(res, dict):
                    return self._decode_content_payload(res)
                return {"value": res}
            except LinearMCPRateLimitError as exc:
                if attempt >= retries:
                    raise
                base = exc.retry_ms / 1000 if exc.retry_ms > 0 else 0.2 * attempt
                time.sleep(base + random.uniform(0, 0.05))
        raise LinearMCPError("unreachable")

    def resolve_team(self, team_key: str) -> dict[str, Any]:
        tool = self._tool_for("resolve_team")
        if tool == "resolve_team":
            return self.call_tool("resolve_team", {"team_key": team_key})
        if tool == "get_team":
            raw = self._decode_content_payload(self.call_tool("get_team", {"query": team_key}))
            teams = self._team_candidates(raw)
        else:
            raw = self._decode_content_payload(self.call_tool("list_teams", {"query": team_key, "limit": 50}))
            teams = self._team_candidates(raw)
            if not teams:
                raw = self._decode_content_payload(self.call_tool("list_teams", {"limit": 250}))
                teams = self._team_candidates(raw)

        if not teams:
            raise LinearMCPError(f"Unable to resolve team from MCP response for key '{team_key}'")
        needle = team_key.strip().lower()
        if not needle:
            raise LinearMCPError("Team key is empty; cannot resolve team")
        exact = []
        for team in teams:
            tid = str(team.get("id") or "").strip().lower()
            tkey = str(team.get("key") or "").strip().lower()
            tname = str(team.get("name") or "").strip().lower()
            if needle in {tid, tkey, tname}:
                exact.append(team)

        if len(exact) == 1:
            team = exact[0]
        elif len(exact) > 1:
            raise LinearMCPError(f"Ambiguous team_key '{team_key}' matches multiple teams")
        else:
            raise LinearMCPError(f"No team matched team_key '{team_key}'")

        team_id = str(team.get("id") or "").strip()
        if not team_id:
            raise LinearMCPError(f"Resolved team missing id for key '{team_key}'")
        return {
            "team_id": team_id,
            "team_key": str(team.get("key") or team_key),
            "team_name": str(team.get("name") or ""),
        }

    def list_workflow_states(self, team_id: str) -> dict[str, Any]:
        tool = self._tool_for("list_workflow_states")
        if tool == "list_workflow_states":
            return self.call_tool("list_workflow_states", {"team_id": team_id})
        raw = self._decode_content_payload(self.call_tool("list_issue_statuses", {"team": team_id}))
        statuses = self._status_candidates(raw)
        return {"states": statuses}

    def create_issue(self, payload: dict[str, Any]) -> dict[str, Any]:
        allowed = {
            "title",
            "description",
            "team",
            "cycle",
            "milestone",
            "priority",
            "project",
            "state",
            "assignee",
            "delegate",
            "labels",
            "dueDate",
            "parentId",
            "estimate",
            "links",
            "blocks",
            "blockedBy",
            "relatedTo",
            "duplicateOf",
        }
        args = {k: v for k, v in payload.items() if k in allowed}
        return self.call_tool("create_issue", args)

    def update_issue(self, issue_id: str, payload: dict[str, Any]) -> dict[str, Any]:
        allowed = {
            "title",
            "description",
            "team",
            "milestone",
            "priority",
            "project",
            "state",
            "cycle",
            "assignee",
            "delegate",
            "labels",
            "parentId",
            "dueDate",
            "estimate",
            "links",
            "blocks",
            "blockedBy",
            "relatedTo",
            "duplicateOf",
        }
        args = {"id": issue_id, **{k: v for k, v in payload.items() if k in allowed}}
        res = self.call_tool("update_issue", args)
        if res.get("updated") is False and "set_labels" in self._tool_names:
            # Legacy adapter compatibility path (fake MCP fixture).
            return self.call_tool("update_issue", {"issue_id": issue_id, **payload})
        return res

    def get_issue(self, issue_id: str) -> dict[str, Any]:
        res = self.call_tool("get_issue", {"id": issue_id})
        if res.get("issue") is None and "set_labels" in self._tool_names:
            return self.call_tool("get_issue", {"issue_id": issue_id})
        if "issue" in res:
            return res
        if isinstance(res.get("id"), str):
            return {"issue": res}
        return res

    def list_issues(self, team_id: str) -> dict[str, Any]:
        res = self.call_tool("list_issues", {"team": team_id})
        if "issues" in res:
            return res
        items = res.get("items")
        if isinstance(items, list):
            return {"issues": items}
        return res

    def add_comment(self, issue_id: str, body: str) -> dict[str, Any]:
        tool = self._tool_for("add_comment")
        if tool == "add_comment":
            return self.call_tool("add_comment", {"issue_id": issue_id, "body": body})
        return self.call_tool("create_comment", {"issueId": issue_id, "body": body})

    def set_labels(self, issue_id: str, labels: list[str]) -> dict[str, Any]:
        tool = self._tool_for("set_labels")
        if tool == "set_labels":
            return self.call_tool("set_labels", {"issue_id": issue_id, "labels": labels})
        return self.call_tool("update_issue", {"id": issue_id, "labels": labels})

    def transition_issue_state(self, issue_id: str, state_id: str) -> dict[str, Any]:
        tool = self._tool_for("transition_issue_state")
        if tool == "transition_issue_state":
            return self.call_tool("transition_issue_state", {"issue_id": issue_id, "state_id": state_id})
        return self.call_tool("update_issue", {"id": issue_id, "state": state_id})

import json
import time
import os
import hashlib
import re
import tempfile
from pathlib import Path
from typing import Any

from src.domain.segment_resolver import resolve_segment_ref


_SURROGATE_RE = re.compile(r"[\ud800-\udfff]")


def _strip_surrogates(obj: Any) -> Any:
    """Recursively remove lone surrogate code points from a JSON-serializable object.

    Surrogates (U+D800-U+DFFF) are illegal in UTF-8 and cannot be written to
    files opened with default encoding. They appear when Python reads files
    with error handlers like ``surrogateescape`` or when binary data is
    decoded lossily.

    Returns a new object with all surrogate characters replaced by the Unicode
    replacement character U+FFFD.
    """
    if isinstance(obj, str):
        return _SURROGATE_RE.sub("\ufffd", obj)
    if isinstance(obj, dict):
        return {k: _strip_surrogates(v) for k, v in obj.items()}
    if isinstance(obj, list):
        return [_strip_surrogates(item) for item in obj]
    return obj


def _relpath(root: Path, target: Path) -> str:
    """Convert target path to relative path for telemetry.

    If target is inside workspace, returns relative path.
    If target is external, returns external/<hash>-<filename>.
    """
    try:
        # Try to make it relative
        rel = target.relative_to(root)
        return str(rel)
    except ValueError:
        # External file - hash the full path for privacy
        path_hash = hashlib.sha256(str(target).encode()).hexdigest()[:8]
        return f"external/{path_hash}-{target.name}"


def _sanitize_value(value: str) -> str:
    """Redact absolute paths/PII from string values.

    Returns:
        Redacted string if value contains PII patterns, otherwise original value.
    """
    # Posix absolute paths
    if value.startswith(("/Users/", "/home/", "/private/var/", "/mnt/c/", "/mnt/C/")):
        return "<ABS_PATH_REDACTED>"

    # Windows paths (C:\Users\, D:\Users\, etc.)
    if len(value) > 2 and value[1:3] == ":\\" and value[0].isalpha():
        if "Users\\" in value or "users\\" in value:
            return "<ABS_PATH_REDACTED>"

    # File URIs
    if value.startswith("file://"):
        return "<ABS_URI_REDACTED>"

    return value


def _sanitize_event(event: dict[str, Any]) -> dict[str, Any]:
    """Sanitize PII from event dict before persisting.

    Sanitizes common path keys: segment, cwd, path, root, repo_root, file, uri.
    Respects TRIFECTA_PII=allow env var for opt-in bypass.
    """
    # Opt-in bypass for debug/local development
    if os.environ.get("TRIFECTA_PII") == "allow":
        return event

    # Keys that commonly contain paths
    PATH_KEYS = ["segment", "cwd", "path", "root", "repo_root", "file", "uri"]

    # Sanitize args.* path keys if present
    if "args" in event and isinstance(event["args"], dict):
        for key in PATH_KEYS:
            if key in event["args"]:
                value = event["args"][key]
                # Only sanitize string values (avoid crash on Path objects, ints, etc.)
                if isinstance(value, str):
                    event["args"][key] = _sanitize_value(value)

    return event


class Telemetry:
    def __init__(self, root: Path | None = None, level: str = "full"):
        # KILL SWITCH: Detect pre-commit or explicit off mode
        # Priority:
        # 1. PRE_COMMIT=1 or level="off" => Complete NO-OP (no dirs, no writes)
        # 2. TRIFECTA_TELEMETRY_DIR => Write to custom dir (for tests)
        # 3. Default => _ctx/telemetry

        self.level = level
        segment_ref = resolve_segment_ref(root or Path.cwd())
        self.root = segment_ref.root_abs
        self.segment_id = segment_ref.fingerprint
        self.segment_label = segment_ref.slug
        self.run_id = os.environ.get("TRIFECTA_RUN_ID", f"run_{int(time.time())}")
        self.metrics: dict[str, int] = {}
        self.timings: dict[str, list[Any]] = {}

        # NO-OP mode: complete disable for pre-commit
        # Use TRIFECTA_NO_TELEMETRY instead of PRE_COMMIT to avoid conflicts
        if level == "off" or os.environ.get("TRIFECTA_NO_TELEMETRY") == "1":
            self.level = "off"  # Force off to ensure event() and flush() are NO-OP
            # Set _ctx_dir but do NOT create, do NOT write
            self._ctx_dir = self.root / "_ctx" / "telemetry"
            return  # Early exit, no directory creation, no file writes

        # Override mode: redirect to custom directory (for tests)
        telemetry_dir_override = os.environ.get("TRIFECTA_TELEMETRY_DIR")
        if telemetry_dir_override:
            self._ctx_dir = Path(telemetry_dir_override)
            self._ctx_dir.mkdir(parents=True, exist_ok=True)
            self._normalize_events_file()
            return

        # Default mode: use _ctx/telemetry in segment
        self._ctx_dir = self.root / "_ctx" / "telemetry"

        # Only create telemetry dir if segment root exists
        # Do NOT create segment root - that would be a hidden side effect
        if not self.root.exists():
            # Segment doesn't exist - disable telemetry (no-op mode)
            # This prevents writing to wrong worktree/repo
            self.level = "off"
            return

        self._ctx_dir.mkdir(parents=True, exist_ok=True)
        self._normalize_events_file()

        # Load prev metrics if needed?
        # For restoration simple start.

    def incr(self, key: str, val: int = 1):
        self.metrics[key] = self.metrics.get(key, 0) + val

    def observe(self, cmd: str, timing_ms: int):
        """Record a timing observation for latency aggregation."""
        if cmd not in self.timings:
            self.timings[cmd] = []
        self.timings[cmd].append(timing_ms)

    def event(self, cmd: str, args: dict[str, Any], result: dict[str, Any], timing_ms: int, **kwargs: Any) -> None:
        if self.level == "off":
            return

        # Reserved key protection (PR#1 contract)
        RESERVED_KEYS = {
            "ts",
            "run_id",
            "segment_id",
            "cmd",
            "args",
            "result",
            "timing_ms",
            "warnings",
            "x",
        }
        collisions = set(kwargs.keys()) & RESERVED_KEYS
        if collisions:
            raise ValueError(f"Cannot use reserved keys: {collisions}")

        # PR#1 compliant event
        # kwargs are put into "x"

        def _summarize_timings(vals: list[int]):
            if not vals:
                return {}
            sorted_vals = sorted(vals)
            n = len(sorted_vals)
            return {
                "count": n,
                "p50_ms": sorted_vals[int(n * 0.5)],
                "p95_ms": sorted_vals[int(n * 0.95)],
                "max_ms": sorted_vals[-1],
            }

        payload = {
            "ts": time.strftime("%Y-%m-%dT%H:%M:%S%z"),
            "run_id": self.run_id,
            "segment_id": self.segment_id,
            "cmd": cmd,
            "args": args,
            "result": result,
            "timing_ms": max(1, timing_ms),
            "warnings": [],
            "x": kwargs,
        }

        # Sanitize PII before persisting
        payload = _sanitize_event(payload)

        # Write to events.jsonl
        with open(self._ctx_dir / "events.jsonl", "a") as f:
            content = json.dumps(_strip_surrogates(payload))
            if not content.endswith("\n"):
                content += "\n"
            f.write(content)

    def flush(self):
        if self.level == "off":
            return
        # Write last_run.json
        # Aggregate logic
        summary = {
            "run_id": self.run_id,
            "segment_id": self.segment_id,
            "ts": time.strftime("%Y-%m-%d %H:%M:%S"),
            "ast": {
                "ast_parse_count": self.metrics.get("ast_parse_count", 0),
                "ast_cache_hit_count": self.metrics.get("ast_cache_hit_count", 0),
                "ast_cache_miss_count": self.metrics.get("ast_cache_miss_count", 0),
            },
            "lsp": {
                "lsp_spawn_count": self.metrics.get("lsp_spawn_count", 0),
                "lsp_ready_count": self.metrics.get("lsp_ready_count", 0),
                "lsp_fallback_count": self.metrics.get("lsp_fallback_count", 0),
                "lsp_request_count": self.metrics.get("lsp_request_count", 0),
            },
            "telemetry_drops": {"drop_rate": 0.0},
        }

        # Add latencies if any timings were observed
        if self.timings:
            latencies = {}
            for cmd, vals in self.timings.items():
                stats = self._compute_stats(vals)
                if stats:
                    latencies[cmd] = stats
            if latencies:
                summary["latencies"] = latencies

        # Add pack_state if present (for T8.2 consistency)
        if hasattr(self, "pack_state") and self.pack_state:
            summary["pack_state"] = self.pack_state

        content = json.dumps(_strip_surrogates(summary), indent=2)
        if not content.endswith("\n"):
            content += "\n"
        with open(self._ctx_dir / "last_run.json", "w") as f:
            f.write(content)

    def _compute_stats(self, vals: list[int]):
        """Compute p50, p95, max from timing values."""
        if not vals:
            return {}
        sorted_vals = sorted(vals)
        n = len(sorted_vals)
        return {
            "count": n,
            "p50_ms": sorted_vals[int(n * 0.5)],
            "p95_ms": sorted_vals[int(n * 0.95)],
            "max_ms": sorted_vals[-1],
        }

    def _normalize_events_file(self) -> None:
        """Best-effort repair for legacy events lacking required schema fields.

        Keeps telemetry tripwires stable by ensuring every persisted row has:
        run_id, segment_id (8-hex), cmd, args, result, timing_ms, warnings, x.
        """
        events_file = self._ctx_dir / "events.jsonl"
        if not events_file.exists():
            return

        try:
            lines = events_file.read_text().splitlines()
        except OSError:
            return

        normalized_lines: list[str] = []
        changed = False

        for line in lines:
            if not line.strip():
                changed = True
                continue
            try:
                row = json.loads(line)
            except json.JSONDecodeError:
                changed = True
                continue

            if not isinstance(row, dict):
                changed = True
                continue

            if "run_id" not in row:
                row["run_id"] = self.run_id
                changed = True

            sid = row.get("segment_id")
            if not isinstance(sid, str) or not re.match(r"^[0-9a-f]{8}$", sid):
                row["segment_id"] = self.segment_id
                changed = True

            if "cmd" not in row:
                row["cmd"] = "telemetry.legacy"
                changed = True
            if "args" not in row or not isinstance(row["args"], dict):
                row["args"] = {}
                changed = True
            if "result" not in row or not isinstance(row["result"], dict):
                row["result"] = {}
                changed = True
            if "timing_ms" not in row:
                row["timing_ms"] = 1
                changed = True
            if "warnings" not in row or not isinstance(row["warnings"], list):
                row["warnings"] = []
                changed = True
            if "x" not in row or not isinstance(row["x"], dict):
                row["x"] = {}
                changed = True

            normalized_lines.append(json.dumps(_strip_surrogates(row)))

        if changed:
            try:
                content = "\n".join(normalized_lines) + ("\n" if normalized_lines else "")
                # Atomic write: write to temp file, then rename (POSIX atomic)
                fd, tmp_path = tempfile.mkstemp(dir=events_file.parent, suffix=".tmp")
                try:
                    with os.fdopen(fd, "w") as f:
                        f.write(content)
                    os.replace(tmp_path, events_file)
                except OSError:
                    # Clean up temp file on failure
                    try:
                        os.unlink(tmp_path)
                    except OSError:
                        pass
                    return
            except OSError:
                return

"""
CLI renderers for repository commands.

This module provides unified rendering functions for repository CLI output,
supporting both JSON and text formats.
"""

import json
from typing import TYPE_CHECKING, Any

import typer

if TYPE_CHECKING:
    from src.application.repo_use_case import RepoEntry


def render_repo_list(
    repos: list["RepoEntry"],
    json_output: bool,
    *,
    legacy_mode: bool = False,
) -> None:
    """
    Render repository list output.

    Args:
        repos: List of repository entries to render.
        json_output: If True, output as JSON; otherwise as text.
        legacy_mode: If True, use legacy format (array without wrapper, no slug).
                     Used for backward compatibility with deprecated alias.
    """
    if json_output:
        if legacy_mode:
            # Legacy format: plain array without slug
            output: Any = [{"repo_id": r.repo_id, "path": r.path} for r in repos]
        else:
            # Modern format: wrapped object with slug
            output = {
                "repos": [
                    {"repo_id": r.repo_id, "path": r.path, "slug": r.slug} for r in repos
                ]
            }
        typer.echo(json.dumps(output, indent=2))
    else:
        if not repos:
            typer.echo("No registered repositories")
        else:
            if legacy_mode:
                # Legacy format: simple list
                for repo in repos:
                    typer.echo(f"{repo.repo_id}: {repo.path}")
            else:
                # Modern format: header with count and slug
                typer.echo(f"Registered Repositories ({len(repos)}):")
                for repo in repos:
                    typer.echo(f"  - {repo.slug}: {repo.repo_id}")


