import subprocess
import json
import shutil
import threading
import os
import sys
import time
from typing import Optional, Dict, Any, List
from enum import Enum
from pathlib import Path


class LSPState(Enum):
    COLD = "COLD"
    WARMING = "WARMING"
    READY = "READY"
    FAILED = "FAILED"
    CLOSED = "CLOSED"


INVARIANT_HANDSHAKE = "handshake_complete"
INVARIANT_PROCESS_ALIVE = "process_alive"
INVARIANT_WORKSPACE_ROOT = "workspace_root_correct"
INVARIANT_HEALTH_CHECK = "health_check_responds"


def _debug_enabled() -> bool:
    value = os.environ.get("TRIFECTA_LSP_DEBUG", "")
    return value.lower() not in {"", "0", "false", "no"}


def _debug_log(message: str) -> None:
    if _debug_enabled():
        sys.stderr.write(f"{message}\n")


def _request_timeout_from_env(default: float = 30.0) -> float:
    raw_value = os.environ.get("TRIFECTA_LSP_REQUEST_TIMEOUT")
    if raw_value is None:
        return default
    try:
        return float(raw_value)
    except ValueError:
        return default


class LSPClient:
    def __init__(self, root_path: Path, telemetry: Any = None):
        self.root_path = root_path
        self.telemetry = telemetry
        self.state = LSPState.COLD
        self.process: Optional[subprocess.Popen[bytes]] = None
        self.lock = threading.Lock()
        self._stop_lock = threading.Lock()
        self.stopping = threading.Event()
        self._thread: Optional[threading.Thread] = None
        self._stderr_thread: Optional[threading.Thread] = None
        self._stderr_lines: List[str] = []
        self._capabilities: Dict[str, Any] = {}
        self._warmup_file: Optional[Path] = None
        self._failed_invariants: List[str] = []

        # Request handling
        self._next_id = 1000
        self._pending_requests: Dict[int, Any] = {}
        self._request_events: Dict[int, threading.Event] = {}

    def start(self) -> None:
        """Start LSP server in background."""
        with self.lock:
            if self.state != LSPState.COLD:
                return

            executable = shutil.which("pylsp") or shutil.which("pyright-langserver")
            if not executable:
                self._transition(LSPState.FAILED)
                self._log_event(
                    "lsp.spawn",
                    {"executable": None},
                    {"status": "failed", "error": "binary_not_found"},
                    0,
                )
                self._emit_fallback("daemon_init", "binary_not_found")
                return

            try:
                self._transition(LSPState.WARMING)
                cmd = [executable]
                if "pyright" in executable:
                    cmd.append("--stdio")

                self.process = subprocess.Popen(
                    cmd,
                    stdin=subprocess.PIPE,
                    stdout=subprocess.PIPE,
                    stderr=subprocess.PIPE,
                    text=False,
                    cwd=str(self.root_path),
                )

                if self.telemetry:
                    self.telemetry.incr("lsp_spawn_count")

                # Robust Sanitize
                exe_log = "unknown"
                try:
                    if executable:
                        exe_log = Path(executable).name
                except Exception:
                    pass

                self._log_event(
                    "lsp.spawn",
                    {"executable": exe_log},
                    {"status": "ok", "pid": self.process.pid},
                    1,
                )

                self._stderr_thread = threading.Thread(target=self._drain_stderr, daemon=True)
                self._stderr_thread.start()

                # Start handshake + Read Loop (save thread reference for join)
                self._thread = threading.Thread(target=self._run_loop, daemon=True)
                self._thread.start()

            except Exception as e:
                self._transition(LSPState.FAILED)
                if self.telemetry:
                    self.telemetry.incr("lsp_failed_count")

                # Capture stderr for debug
                err_out = "Unknown"
                if self.process:
                    try:
                        _, stderr_data = self.process.communicate(timeout=0.2)
                        if stderr_data:
                            err_out = stderr_data.decode("utf-8")
                    except Exception:
                        pass
                _debug_log(f"DEBUG: LSP Start Failed: {e}. Stderr: {err_out}")

                # Sanitize executable path for telemetry
                exe_name = "unknown"
                if executable:
                    exe_name = Path(executable).name

                self._log_event(
                    "lsp.spawn", {"executable": exe_name}, {"status": "error", "error": str(e)}, 0
                )

    def stop(self) -> None:
        """Strict cleanup: signal -> terminate -> join thread -> close streams.

        SHUTDOWN ORDER INVARIANT (do not reorder):
          1. Set stopping flag (signal intent)
          2. Terminate process
          3. Join loop thread (wait for exit)
          4. Close streams (only after thread exits)

        Idempotent: safe to call multiple times.
        """
        with self._stop_lock:
            # 1. Signal threads first (defensive: stopping should only be set here)
            if not self.stopping.is_set():
                self.stopping.set()

            # 2. Check/set state (idempotent)
            with self.lock:
                if self.state == LSPState.CLOSED:
                    return
                self.state = LSPState.CLOSED

            # 3. Terminate process
            if self.process:
                try:
                    self.process.terminate()
                    try:
                        self.process.wait(timeout=0.5)
                    except subprocess.TimeoutExpired:
                        self.process.kill()
                        self.process.wait(timeout=0.2)
                except Exception:
                    pass  # Process might be gone

            # 4. Join background threads BEFORE closing streams
            # Increased timeout for CI stability (was 0.5s)
            if self._stderr_thread and self._stderr_thread.is_alive():
                self._stderr_thread.join(timeout=0.5)
            if self._thread and self._thread.is_alive():
                self._thread.join(timeout=1.0)

                # CRITICAL: If thread still alive after join, DO NOT close streams
                # This avoids write-to-closed-file race in edge cases (blocked I/O)
                # Better to leak streams in rare shutdown failure than reintroduce bug
                if self._thread.is_alive():
                    # Thread didn't terminate cleanly; leave streams open
                    # Process is already terminated, thread will eventually exit on EOF
                    return

            # 5. Close streams ONLY after thread exits
            if self.process:
                try:
                    if self.process.stdin:
                        self.process.stdin.close()
                    if self.process.stdout:
                        self.process.stdout.close()
                    if self.process.stderr:
                        self.process.stderr.close()
                except Exception:
                    pass  # Already closed

    def _drain_stderr(self) -> None:
        """Drain stderr to avoid child-process pipe backpressure."""
        max_stderr_lines = 50
        try:
            if not self.process or not self.process.stderr:
                return
            for raw_line in self.process.stderr:
                if self.stopping.is_set():
                    break
                try:
                    line = raw_line.decode("utf-8", errors="replace").rstrip()
                except Exception:
                    line = repr(raw_line)
                self._stderr_lines.append(line)
                if len(self._stderr_lines) > max_stderr_lines:
                    self._stderr_lines = self._stderr_lines[-max_stderr_lines:]
        except (OSError, ValueError):
            pass

    def did_open(self, file_path: Path, content: str) -> None:
        """Notify file open to trigger diagnostics."""
        with self.lock:
            if self.state == LSPState.CLOSED or not self.process:
                return

        self._warmup_file = file_path
        msg = {
            "jsonrpc": "2.0",
            "method": "textDocument/didOpen",
            "params": {
                "textDocument": {
                    "uri": file_path.as_uri(),
                    "languageId": "python",
                    "version": 1,
                    "text": content,
                }
            },
        }
        self._send_rpc(msg)

    def is_ready(self) -> bool:
        return self.state == LSPState.READY

    def _transition(self, new_state: LSPState) -> None:
        # Track READY invariant failures
        if new_state == LSPState.FAILED and self.state != LSPState.FAILED:
            if self.telemetry:
                self.telemetry.incr("lsp.ready_fail_invariant")
        self.state = new_state

    def _log_event(
        self, cmd: str, args: Dict[str, Any], result: Dict[str, Any], timing: int, **kwargs: Any
    ) -> None:
        if self.telemetry:
            # kwargs are passed to event as x_fields
            self.telemetry.event(cmd, args, result, timing, lsp_state=self.state.value, **kwargs)

    def _emit_fallback(self, requested_method: str, reason: str) -> None:
        """Emit lsp.fallback telemetry event when LSP is unavailable.

        This makes fallback behavior explicit and observable, allowing
        monitoring of how often AST fallback is used instead of LSP.

        Args:
            requested_method: The LSP method that was requested (e.g., "textDocument/definition")
            reason: Why fallback occurred (e.g., "state_not_ready:COLD", "request_timeout")
        """
        self._log_event(
            "lsp.fallback",
            {"requested_method": requested_method},
            {"status": "fallback_to_ast", "reason": reason},
            0,
            fallback_to="ast",
        )
        if self.telemetry:
            self.telemetry.incr("lsp_fallback_count", 1)

    def _run_loop(self) -> None:
        try:
            req = {
                "jsonrpc": "2.0",
                "id": 1,
                "method": "initialize",
                "params": {
                    "processId": os.getpid(),
                    "rootUri": self.root_path.as_uri(),
                    "capabilities": {},
                },
            }
            self._send_rpc(req)

            resp = None
            for _ in range(50):
                msg = self._read_rpc()
                if not msg:
                    break
                if msg.get("id") == 1 and ("result" in msg or "error" in msg):
                    resp = msg
                    break
                _debug_log(
                    f"[LSP_HANDSHAKE_SKIP] id={msg.get('id')} method={msg.get('method', '')}"
                )
            if not resp or "result" not in resp:
                self._failed_invariants.append(INVARIANT_HANDSHAKE)
                self._transition(LSPState.FAILED)
                return

            self._capabilities = resp["result"].get("capabilities", {})
            self._send_rpc({"jsonrpc": "2.0", "method": "initialized", "params": {}})

            if not self._check_invariants():
                self._log_event(
                    "lsp.state_change",
                    {},
                    {"status": "failed", "reason": "invariant_check_failed"},
                    1,
                    reason="invariant_check_failed",
                    failed_invariants=",".join(self._failed_invariants),
                )
                self._transition(LSPState.FAILED)
                return

            with self.lock:
                self._transition(LSPState.READY)

            if self.telemetry:
                self.telemetry.incr("lsp_ready_count")
                self._log_event(
                    "lsp.state_change",
                    {},
                    {"status": "ready"},
                    1,
                    reason="invariants_passed",
                )

            saw_post_init_message = False
            while self.state != LSPState.CLOSED:
                msg = self._read_rpc()
                if not msg:
                    break
                saw_post_init_message = True

                msg_id = msg.get("id")
                msg_method = msg.get("method", "")
                has_result = "result" in msg
                has_error = "error" in msg

                if msg_id is not None:
                    with self.lock:
                        is_pending = msg_id in self._pending_requests
                    result_type = type(msg.get("result")).__name__ if has_result else "none"
                    _debug_log(
                        f"[LSP_LOOP_MSG] id={msg_id} method={msg_method} "
                        f"has_result={has_result} has_error={has_error} "
                        f"is_pending={is_pending} result_type={result_type}"
                    )

                if "id" in msg and ("result" in msg or "error" in msg):
                    req_id = msg["id"]
                    with self.lock:
                        if req_id in self._pending_requests:
                            if "result" in msg:
                                self._pending_requests[req_id] = msg["result"]
                                _debug_log(
                                    f"[LSP_LOOP_SET] id={req_id} result_type={type(msg['result']).__name__}"
                                )
                            else:
                                self._pending_requests[req_id] = {
                                    "__lsp_error__": True,
                                    "error": msg["error"],
                                }
                                _debug_log(f"[LSP_LOOP_ERROR] id={req_id} error={msg['error']}")
                            self._request_events[req_id].set()
                        else:
                            _debug_log(f"[LSP_LOOP_ORPHAN] id={req_id} not in pending")

                if msg_method == "textDocument/publishDiagnostics":
                    pass

            # Relaxed READY compatibility:
            # when tests drive _run_loop() without a real process, require at least
            # one post-initialize message to keep READY; immediate EOF is failed.
            if self.process is None and not saw_post_init_message:
                self._failed_invariants.append(INVARIANT_PROCESS_ALIVE)
                self._transition(LSPState.FAILED)
                return
        except Exception as e:
            if self.stopping.is_set():
                return

            err_out = "Unknown"
            if self.process:
                try:
                    _, stderr_data = self.process.communicate(timeout=0.2)
                    if stderr_data:
                        err_out = stderr_data.decode("utf-8")
                except Exception:
                    pass
            _debug_log(f"DEBUG: LSP Loop Exception: {e}. Stderr: {err_out}")
            self._failed_invariants.append(INVARIANT_HANDSHAKE)
            self._transition(LSPState.FAILED)

    def _check_invariants(self) -> bool:
        self._failed_invariants.clear()

        # Compatibility mode for direct _run_loop() tests without spawned process.
        # Final state is validated after loop based on post-initialize activity.
        if self.process is None:
            return True

        if not self._verify_process_alive():
            return False

        if not self._verify_workspace_root():
            return False

        if not self._verify_health_check():
            return False

        return True

    def _verify_process_alive(self) -> bool:
        if not self.process or self.process.poll() is not None:
            self._failed_invariants.append(INVARIANT_PROCESS_ALIVE)
            return False
        return True

    def _verify_workspace_root(self) -> bool:
        if not self.root_path or not self.root_path.exists():
            self._failed_invariants.append(INVARIANT_WORKSPACE_ROOT)
            return False
        return True

    def _verify_health_check(self) -> bool:
        if not self._capabilities:
            self._failed_invariants.append(INVARIANT_HEALTH_CHECK)
            return False
        return True

    def health_check(self, timeout_ms: int = 500) -> bool:
        if self.state != LSPState.READY:
            return False

        start = time.perf_counter()
        result = self.request("$/health", {}, timeout=timeout_ms / 1000.0)
        elapsed_ms = int((time.perf_counter() - start) * 1000)

        if result is not None and elapsed_ms <= timeout_ms:
            return True

        if elapsed_ms > timeout_ms:
            self._failed_invariants.append(f"{INVARIANT_HEALTH_CHECK}_timeout")
            self._log_event(
                "lsp.health_check",
                {},
                {"status": "timeout", "latency_ms": elapsed_ms},
                elapsed_ms,
            )

        return False

    def get_failed_invariants(self) -> List[str]:
        return self._failed_invariants.copy()

    def request(
        self, method: str, params: Dict[str, Any], timeout: float | None = None
    ) -> Optional[Dict[str, Any]]:
        """Send a request and wait for the response."""
        if timeout is None:
            timeout = _request_timeout_from_env()
        with self.lock:
            if self.state != LSPState.READY:
                self._emit_fallback(method, f"state_not_ready:{self.state.value}")
                return None

            req_id = self._next_id
            self._next_id += 1
            event = threading.Event()
            self._pending_requests[req_id] = None  # Placeholder
            self._request_events[req_id] = event

        msg = {"jsonrpc": "2.0", "id": req_id, "method": method, "params": params}
        self._send_rpc(msg)

        _debug_log(f"[LSP_REQ_SENT] id={req_id} method={method} timeout={timeout}")

        # Wait for response
        waited = event.wait(timeout)
        _debug_log(f"[LSP_REQ_WAIT] id={req_id} waited={waited}")

        if waited:
            with self.lock:
                result = self._pending_requests.pop(req_id, None)
                self._request_events.pop(req_id, None)
                if isinstance(result, dict) and result.get("__lsp_error__"):
                    err_detail = result.get("error", {})
                    self._emit_fallback(
                        method,
                        f"lsp_error:{err_detail.get('code', 'unknown')}:{err_detail.get('message', '')}",
                    )
                    return None
                _debug_log(
                    f"[LSP_REQ_RESULT] id={req_id} type={type(result).__name__} "
                    f"is_dict={isinstance(result, dict)} "
                    f"has_contents={bool(result.get('contents')) if isinstance(result, dict) else False}"
                )
                return result if isinstance(result, dict) else None
        else:
            with self.lock:
                self._pending_requests.pop(req_id, None)
                self._request_events.pop(req_id, None)
                self._emit_fallback(method, "request_timeout")
                _debug_log(f"[LSP_REQ_TIMEOUT] id={req_id} method={method}")
                return None  # Timeout

    def _send_rpc(self, msg: Dict[str, Any]) -> bool:
        # Don't attempt writes if stopping
        if self.stopping.is_set():
            return False
        if not self.process or not self.process.stdin:
            return False
        try:
            content = json.dumps(msg).encode("utf-8")
            header = f"Content-Length: {len(content)}\r\n\r\n".encode("ascii")
            self.process.stdin.write(header + content)
            self.process.stdin.flush()
            return True
        except (OSError, ValueError, BrokenPipeError):
            # Silently ignore write errors during shutdown
            return False

    def _read_rpc(self) -> Optional[Dict[str, Any]]:
        if not self.process or not self.process.stdout:
            return None
        try:
            # Read Headers
            length = None
            while True:
                line = self.process.stdout.readline()
                if not line:
                    if length is None:
                        # EOF before any headers
                        return None
                    # EOF inside headers? Break and try reading content?
                    break

                line = line.strip()
                if not line:
                    # End of headers
                    break

                if line.startswith(b"Content-Length: "):
                    length = int(line.split(b": ")[1])

            if length is None:
                return None

            # Read Content
            content = b""
            while len(content) < length:
                chunk = self.process.stdout.read(length - len(content))
                if not chunk:
                    break
                content += chunk

            # Parse JSON
            try:
                msg = json.loads(content.decode("utf-8"))
                # Type guard for mypy
                return msg if isinstance(msg, dict) else None
            except json.JSONDecodeError:
                return None
        except Exception:
            return None

from pathlib import Path
from typing import Any

import yaml

from src.domain.linear_models import LinearPolicy, REQUIRED_DRIFT_LEVELS, REQUIRED_TRIFECTA_STATUSES


class LinearPolicyError(ValueError):
    pass


_REQUIRED_KEYS = {
    "mode",
    "direction",
    "policy_version",
    "outbound_allow",
    "inbound_allow",
    "drift_severity",
    "status_map",
}


def _must_have_keys(data: dict[str, Any]) -> None:
    for key in sorted(_REQUIRED_KEYS):
        if key not in data:
            raise LinearPolicyError(f"missing required key: {key}")


def _validate_mode_and_direction(data: dict[str, Any]) -> None:
    if data.get("mode") != "viewer":
        raise LinearPolicyError("mode must be 'viewer'")
    if data.get("direction") != "outbound":
        raise LinearPolicyError("direction must be 'outbound'")


def _validate_teams(data: dict[str, Any]) -> tuple[str, str]:
    team_key = str(data.get("team_key") or "").strip()
    team_id = str(data.get("team_id") or "").strip()
    if not team_key and not team_id:
        raise LinearPolicyError("team_key or team_id is required")
    return team_key, team_id


def _validate_allowlists(data: dict[str, Any]) -> tuple[tuple[str, ...], tuple[str, ...]]:
    outbound_allow = data.get("outbound_allow")
    inbound_allow = data.get("inbound_allow")
    if not isinstance(outbound_allow, list) or not all(isinstance(x, str) for x in outbound_allow):
        raise LinearPolicyError("outbound_allow must be a list of strings")
    if not isinstance(inbound_allow, list) or not all(isinstance(x, str) for x in inbound_allow):
        raise LinearPolicyError("inbound_allow must be a list of strings")
    if inbound_allow:
        raise LinearPolicyError("inbound_allow must be empty in viewer mode")
    return tuple(outbound_allow), tuple(inbound_allow)


def _validate_drift_severity(data: dict[str, Any]) -> dict[str, tuple[str, ...]]:
    value = data.get("drift_severity")
    if not isinstance(value, dict):
        raise LinearPolicyError("drift_severity must be a mapping")

    resolved: dict[str, tuple[str, ...]] = {}
    for level in REQUIRED_DRIFT_LEVELS:
        fields = value.get(level)
        if not isinstance(fields, list) or not all(isinstance(x, str) for x in fields):
            raise LinearPolicyError(f"drift_severity.{level} must be a list of strings")
        resolved[level] = tuple(fields)
    return resolved


def _validate_status_map(data: dict[str, Any]) -> dict[str, str | None]:
    value = data.get("status_map")
    if not isinstance(value, dict):
        raise LinearPolicyError("status_map must be a mapping")
    resolved: dict[str, str | None] = {}
    for status in REQUIRED_TRIFECTA_STATUSES:
        if status not in value:
            raise LinearPolicyError(f"status_map missing key: {status}")
        state_id = value[status]
        if state_id is not None and not isinstance(state_id, str):
            raise LinearPolicyError(f"status_map.{status} must be string or null")
        resolved[status] = state_id
    return resolved


def load_linear_policy(path: Path) -> LinearPolicy:
    if not path.exists():
        raise LinearPolicyError(f"policy file not found: {path}")

    try:
        raw = yaml.safe_load(path.read_text(encoding="utf-8"))
    except yaml.YAMLError as exc:
        raise LinearPolicyError(f"invalid YAML policy: {exc}") from exc

    if not isinstance(raw, dict):
        raise LinearPolicyError("policy root must be a mapping")

    _must_have_keys(raw)
    _validate_mode_and_direction(raw)
    team_key, team_id = _validate_teams(raw)
    outbound_allow, inbound_allow = _validate_allowlists(raw)
    drift_severity = _validate_drift_severity(raw)
    status_map = _validate_status_map(raw)

    policy_version = str(raw.get("policy_version") or "").strip()
    if not policy_version:
        raise LinearPolicyError("policy_version must be non-empty")
    project = str(raw.get("project") or "").strip()

    return LinearPolicy(
        mode="viewer",
        direction="outbound",
        policy_version=policy_version,
        team_key=team_key,
        team_id=team_id,
        outbound_allow=outbound_allow,
        inbound_allow=inbound_allow,
        drift_severity=drift_severity,
        status_map=status_map,
        project=project,
    )

"""Domain models for discovery operations."""

from dataclasses import dataclass


@dataclass(frozen=True)
class ImportInfo:
    """Represents an imported module or symbol."""

    name: str
    is_relative: bool
    level: int
    imported_names: tuple[str, ...]

    @property
    def is_from_import(self) -> bool:
        """Whether this is a 'from X import Y' statement."""
        return len(self.imported_names) > 0

    @property
    def is_wildcard(self) -> bool:
        """Whether this imports everything (from X import *)."""
        return "*" in self.imported_names


@dataclass(frozen=True)
class ExtractionResult:
    """Result of extracting imports from a source file."""

    imports: tuple[ImportInfo, ...]
    line_count: int
    warnings: tuple[str, ...]

"""
Functional Result Monad for Railway Oriented Programming.

Inspired by Rust's Result<T, E> and Haskell's Either.
Pure domain module - no external dependencies.

Author: Trifecta Team
Date: 2025-12-31
"""

from __future__ import annotations

from dataclasses import dataclass
from typing import Callable, Generic, TypeAlias, TypeVar

T = TypeVar("T")  # Success type
E = TypeVar("E")  # Error type
U = TypeVar("U")  # Mapped type


@dataclass(frozen=True)
class Ok(Generic[T]):
    """Represents a successful result."""

    value: T

    def is_ok(self) -> bool:
        """Return True if this is an Ok result."""
        return True

    def is_err(self) -> bool:
        """Return False since this is not an Err."""
        return False

    def unwrap(self) -> T:
        """Extract the success value. For tests/ergonomics only."""
        return self.value

    def unwrap_err(self) -> None:
        """Raise ValueError since this is not an Err. For tests only."""
        raise ValueError("Called unwrap_err on Ok")

    def map(self, fn: Callable[[T], U]) -> Ok[U]:
        """Apply function to success value, returning new Ok."""
        return Ok(fn(self.value))

    def and_then(self, fn: Callable[[T], Result[U, E]]) -> Result[U, E]:
        """Chain with another Result-returning function."""
        return fn(self.value)


@dataclass(frozen=True)
class Err(Generic[E]):
    """Represents a failed result."""

    error: E

    def is_ok(self) -> bool:
        """Return False since this is not an Ok."""
        return False

    def is_err(self) -> bool:
        """Return True if this is an Err result."""
        return True

    def unwrap(self) -> None:
        """Raise ValueError since this is an Err. For tests only."""
        raise ValueError(f"Called unwrap on Err: {self.error}")

    def unwrap_err(self) -> E:
        """Extract the error value. For tests/ergonomics only."""
        return self.error

    def map(self, fn: Callable[[T], U]) -> Err[E]:
        """Error propagates unchanged (short-circuit)."""
        return self

    def and_then(self, fn: Callable[[T], Result[U, E]]) -> Err[E]:
        """Error propagates unchanged (short-circuit)."""
        return self


# Type alias for Result union (Python 3.12+ compatible)
# With __future__ annotations, this is only evaluated during type checking
Result: TypeAlias = Ok[T] | Err[E]


def is_ok(result: Result[T, E]) -> bool:
    """Type guard to check if a Result is Ok."""
    return result.is_ok()

"""Skill manifest domain model for skill_hub indexing.

Schema v2 contract:
- id: stable skill identifier (e.g., "skill:my-skill")
- name: human-readable name
- relative_path: path relative to segment root
- description: description for search
- source: source collection

Fail-closed: Invalid entries cause Err, not silent skip.

Author: Trifecta Team
Date: 2026-03-19
"""

from __future__ import annotations

import hashlib
import json
import logging
from dataclasses import dataclass, field
from pathlib import Path

from src.domain.result import Err, Ok, Result

logger = logging.getLogger(__name__)

# Required fields for schema v2
REQUIRED_FIELDS = ("id", "name", "relative_path", "description", "source")


@dataclass(frozen=True)
class SkillManifestEntry:
    """A single skill entry in the manifest."""

    id: str
    name: str
    relative_path: str
    description: str
    source: str
    canonical: bool = True
    tags: tuple[str, ...] = field(default_factory=tuple)

    @property
    def skill_id(self) -> str:
        """
        Stable identity of this skill.
        Does not change between builds.
        Format: skill:{name}
        """
        return self.id

    @property
    def chunk_id(self) -> str:
        """
        Chunk identifier including content hash.
        CHANGES when content changes.
        Format: skill:{name}:{content_hash}
        """
        # Use name (not skill_id which includes skill: prefix)
        return f"skill:{self.name}:{self._content_hash}"

    _content_hash: str = field(default="", repr=False)

    @classmethod
    def from_dict(
        cls, data: dict[str, object], content_hash: str = ""
    ) -> "SkillManifestEntry":
        """Create entry from dictionary."""
        return cls(
            id=str(data.get("id", "")),
            name=str(data.get("name", "")),
            relative_path=str(data.get("relative_path", "")),
            description=str(data.get("description", "")),
            source=str(data.get("source", "")),
            canonical=bool(data.get("canonical", True)),
            tags=tuple(data.get("tags", []) or []),  # type: ignore
            _content_hash=content_hash,
        )


@dataclass(frozen=True)
class SkillManifest:
    """
    Manifest of discoverable skills for a skill_hub segment.

    Schema v2: Only entries in this manifest are discoverable.
    Fail-closed: Invalid manifest causes Err, not degradation.
    """

    schema_version: int
    skills: tuple[SkillManifestEntry, ...]

    def find_by_relative_path(self, relative_path: str) -> SkillManifestEntry | None:
        """Find a skill by its relative path."""
        for skill in self.skills:
            if skill.relative_path == relative_path:
                return skill
        return None

    def find_by_name(self, name: str) -> SkillManifestEntry | None:
        """Find a skill by its name."""
        for skill in self.skills:
            if skill.name == name:
                return skill
        return None

    @classmethod
    def load(
        cls, manifest_path: Path, segment_path: Path
    ) -> Result["SkillManifest", list[str]]:
        """
        Load and validate manifest from disk.

        Args:
            manifest_path: Path to skills_manifest.json
            segment_path: Path to segment root (for file validation)

        Returns:
            Ok(SkillManifest) if valid
            Err(list[str]) with error messages if invalid

        Fail-closed: Any validation error returns Err.
        """
        errors: list[str] = []

        # 1. Check file exists
        if not manifest_path.exists():
            return Err([f"Manifest not found: {manifest_path}"])

        # 2. Parse JSON
        try:
            raw_content = manifest_path.read_text(encoding="utf-8")
            data = json.loads(raw_content)
        except json.JSONDecodeError as e:
            return Err([f"Failed to parse manifest JSON: {e}"])
        except OSError as e:
            return Err([f"Failed to read manifest: {e}"])

        if not isinstance(data, dict):
            return Err([f"Manifest must be a JSON object, got {type(data).__name__}"])

        # 3. Detect schema version
        schema_version = data.get("schema_version", 1)

        # 4. Migrate if needed
        if schema_version == 1:
            migration_result = cls._migrate_v1_to_v2(data, segment_path)
            if isinstance(migration_result, Err):
                return migration_result
            data = migration_result.value
            schema_version = 2

        # 5. Validate and build entries
        skills_data = data.get("skills", [])
        if not isinstance(skills_data, list):
            return Err([f"'skills' must be a list, got {type(skills_data).__name__}"])

        valid_entries: list[SkillManifestEntry] = []

        for i, skill_data in enumerate(skills_data):
            if not isinstance(skill_data, dict):
                errors.append(f"Entry {i}: must be an object, got {type(skill_data).__name__}")
                continue

            # Validate required fields
            for field_name in REQUIRED_FIELDS:
                if field_name not in skill_data or not skill_data[field_name]:
                    errors.append(
                        f"Entry {i}: missing required field '{field_name}'"
                    )

            if errors:
                continue  # Skip further validation for this entry

            # Validate file exists
            relative_path = str(skill_data.get("relative_path", ""))
            file_path = segment_path / relative_path
            if not file_path.exists():
                errors.append(
                    f"Entry {i} '{skill_data.get('name', '?')}': "
                    f"file not found: {relative_path}"
                )
                continue

            # Compute content hash
            content_hash = cls._compute_content_hash(file_path)

            # Build entry
            entry = SkillManifestEntry.from_dict(skill_data, content_hash)
            valid_entries.append(entry)

        if errors:
            return Err(errors)

        return Ok(
            cls(
                schema_version=schema_version,
                skills=tuple(valid_entries),
            )
        )

    @classmethod
    def admit_and_persist(
        cls,
        manifest_path: Path,
        segment_path: Path,
        declared_policy: str,
    ) -> Result["SkillManifest", list[str]]:
        """Admission boundary for skill_hub manifests (normalize -> validate -> persist)."""
        admitted = cls.admit(
            manifest_path,
            segment_path,
            declared_policy=declared_policy,
        )
        if isinstance(admitted, Err):
            return admitted

        manifest, canonical_doc = admitted.value
        try:
            manifest_path.write_text(
                json.dumps(canonical_doc, indent=2, ensure_ascii=False) + "\n",
                encoding="utf-8",
            )
        except OSError as e:
            return Err([f"[Provenance] Failed to persist canonical manifest: {e}"])

        return Ok(manifest)

    @classmethod
    def admit(
        cls,
        manifest_path: Path,
        segment_path: Path,
        declared_policy: str,
    ) -> Result[tuple["SkillManifest", dict[str, object]], list[str]]:
        """Admission boundary for skill_hub manifests (normalize + validate, no persistence)."""
        errors: list[str] = []

        if declared_policy != "skill_hub":
            return Err([
                "[Policy consistency] Admission requires declared policy 'skill_hub'"
            ])

        if not manifest_path.exists():
            return Err([f"[Shape] Manifest not found: {manifest_path}"])

        try:
            raw_data = json.loads(manifest_path.read_text(encoding="utf-8"))
        except json.JSONDecodeError as e:
            return Err([f"[Shape] Failed to parse manifest JSON: {e}"])
        except OSError as e:
            return Err([f"[Shape] Failed to read manifest: {e}"])

        if not isinstance(raw_data, dict):
            return Err([f"[Shape] Manifest must be a JSON object, got {type(raw_data).__name__}"])

        input_schema = raw_data.get("schema_version", 1)

        if input_schema == 1:
            migrated = cls._migrate_v1_to_v2(raw_data, segment_path)
            if isinstance(migrated, Err):
                return Err([f"[Shape] {e}" for e in migrated.error])
            canonical_data = migrated.value
        elif input_schema == 2:
            canonical_data = raw_data
        else:
            return Err([f"[Shape] Unsupported schema_version: {input_schema}"])

        skills_data = canonical_data.get("skills", [])
        if not isinstance(skills_data, list):
            return Err([f"[Shape] 'skills' must be a list, got {type(skills_data).__name__}"])

        canonical_skills: list[dict[str, object]] = []
        seen_ids: set[str] = set()
        seen_paths: set[str] = set()

        for i, raw_skill in enumerate(skills_data):
            if not isinstance(raw_skill, dict):
                errors.append(f"[Shape] Entry {i}: must be an object")
                continue

            if "canonical" not in raw_skill:
                errors.append(f"[Shape] Entry {i}: missing required field 'canonical'")
                continue

            skill_id = str(raw_skill.get("id", "")).strip()
            name = str(raw_skill.get("name", "")).strip()
            relative_path = str(raw_skill.get("relative_path", "")).strip()
            description = str(raw_skill.get("description", "")).strip()
            source = str(raw_skill.get("source", "")).strip()
            canonical = raw_skill.get("canonical")
            tags = raw_skill.get("tags", [])

            if not skill_id.startswith("skill:"):
                errors.append(f"[Shape] Entry {i}: id must start with 'skill:'")
            if not name:
                errors.append(f"[Shape] Entry {i}: missing required field 'name'")
            if not relative_path:
                errors.append(f"[Shape] Entry {i}: missing required field 'relative_path'")
            if not description:
                errors.append(f"[Shape] Entry {i}: missing required field 'description'")
            if not source:
                errors.append(f"[Shape] Entry {i}: missing required field 'source'")
            if not isinstance(canonical, bool):
                errors.append(f"[Shape] Entry {i}: 'canonical' must be boolean")

            if not relative_path or Path(relative_path).is_absolute() or ".." in Path(relative_path).parts:
                errors.append(f"[Shape] Entry {i}: invalid relative_path '{relative_path}'")
                continue

            if skill_id in seen_ids:
                errors.append(f"[Closure] Entry {i}: duplicate id '{skill_id}'")
            else:
                seen_ids.add(skill_id)

            if relative_path in seen_paths:
                errors.append(f"[Closure] Entry {i}: duplicate relative_path '{relative_path}'")
            else:
                seen_paths.add(relative_path)

            file_path = segment_path / relative_path
            if canonical is True and not file_path.exists():
                errors.append(f"[Closure] Entry {i}: canonical file not found: {relative_path}")

            canonical_skills.append(
                {
                    "id": skill_id,
                    "name": name,
                    "relative_path": relative_path,
                    "description": description,
                    "source": source,
                    "canonical": canonical,
                    "tags": tags if isinstance(tags, list) else [],
                }
            )

        if errors:
            return Err(errors)

        canonical_doc = {
            "schema_version": 2,
            "skills": canonical_skills,
        }

        canonical_entries: list[SkillManifestEntry] = []
        for skill_data in canonical_skills:
            relative_path = str(skill_data["relative_path"])
            file_path = segment_path / relative_path
            content_hash = cls._compute_content_hash(file_path)
            canonical_entries.append(
                SkillManifestEntry.from_dict(skill_data, content_hash)
            )

        return Ok(
            (
                cls(schema_version=2, skills=tuple(canonical_entries)),
                canonical_doc,
            )
        )

    @staticmethod
    def validate_pack_admission(
        manifest: "SkillManifest",
        *,
        declared_policy: str,
        pack_chunk_ids: list[str],
        pack_docs: list[str],
        pack_source_paths: list[str],
    ) -> Result[None, list[str]]:
        """Validate skill_hub pack admission checks at the policy boundary."""
        errors: list[str] = []

        if declared_policy != "skill_hub":
            errors.append("[Policy consistency] Promotion request must declare 'skill_hub'")

        if any(not chunk_id.startswith("skill:") for chunk_id in pack_chunk_ids):
            errors.append("[Shape] Pack contains non skill:* chunk IDs")

        if any(doc != "skill" for doc in pack_docs):
            errors.append("[Shape] Pack contains non-skill docs")

        manifest_paths = {
            skill.relative_path for skill in manifest.skills if skill.canonical
        }
        pack_paths = set(pack_source_paths)

        if pack_paths != manifest_paths:
            missing = sorted(manifest_paths - pack_paths)
            extra = sorted(pack_paths - manifest_paths)
            if missing:
                errors.append(f"[Closure] Missing pack entries for canonical manifest paths: {missing}")
            if extra:
                errors.append(f"[Closure] Pack contains non-canonical paths: {extra}")

        if errors:
            return Err(errors)
        return Ok(None)

    @staticmethod
    def _compute_content_hash(file_path: Path) -> str:
        """Compute SHA256 hash of file content."""
        content = file_path.read_text(encoding="utf-8")
        return hashlib.sha256(content.encode()).hexdigest()[:10]

    @classmethod
    def _migrate_v1_to_v2(
        cls, v1_data: dict[str, object], segment_path: Path
    ) -> Result[dict[str, object], list[str]]:
        """
        Migrate schema_version 1 to 2.

        v1 uses: source_path (absolute path to SKILL.md)
        v2 uses: relative_path (relative to segment root)

        Rejects ambiguous cases:
        - source_path not ending in /SKILL.md
        - derived file not found in segment
        """
        errors: list[str] = []
        skills_v2: list[dict[str, object]] = []

        skills_v1 = v1_data.get("skills", [])
        if not isinstance(skills_v1, list):
            return Err([f"'skills' must be a list, got {type(skills_v1).__name__}"])

        for i, skill in enumerate(skills_v1):
            if not isinstance(skill, dict):
                errors.append(f"Entry {i}: must be an object")
                continue

            source_path = skill.get("source_path", "")
            if not source_path:
                errors.append(f"Entry {i}: missing source_path")
                continue

            # Validate pattern: must end with /SKILL.md
            if not source_path.endswith("/SKILL.md"):
                errors.append(
                    f"Entry {i}: source_path must end with '/SKILL.md', got: {source_path}"
                )
                continue

            # Derive relative_path from source_path
            # /abs/path/to/skill-name/SKILL.md -> skill-name.md
            skill_dir = Path(source_path).parent.name
            if not skill_dir:
                errors.append(f"Entry {i}: cannot derive skill name from source_path")
                continue

            relative_path = f"{skill_dir}.md"

            # Validate file exists
            expected_file = segment_path / relative_path
            if not expected_file.exists():
                errors.append(f"Entry {i}: derived file not found: {relative_path}")
                continue

            # Generate stable skill_id
            skill_id = f"skill:{skill_dir}"

            # Build v2 entry
            skills_v2.append({
                "id": skill_id,
                "name": skill.get("name", skill_dir),
                "relative_path": relative_path,
                "description": skill.get("description", ""),
                "source": skill.get("source", "unknown"),
                "canonical": skill.get("canonical", True),
                "tags": skill.get("tags", []),
            })

        if errors:
            return Err(errors)

        return Ok({
            "schema_version": 2,
            "skills": skills_v2,
        })

"""
Skill metadata contracts for Trifecta skill system.

Pure domain module - no external dependencies.
Uses dataclasses and Result pattern for validation.

Author: Trifecta Team
Date: 2026-03-05
"""

from __future__ import annotations

from dataclasses import dataclass, field

from src.domain.result import Ok, Err, Result


# Valid input types for skill inputs (used in validation, not type annotation)
VALID_INPUT_TYPES: tuple[str, ...] = ("string", "file", "json", "boolean", "number")


@dataclass(frozen=True)
class SkillValidationError:
    """A single validation error for skill metadata."""

    field: str
    message: str
    value: object | None = None

    def __str__(self) -> str:
        if self.value is not None:
            return f"{self.field}: {self.message} (got: {self.value!r})"
        return f"{self.field}: {self.message}"


@dataclass(frozen=True)
class SkillInput:
    """An input parameter for a skill."""

    name: str
    type: str  # Validated by validate_skill_input, not here (no exceptions in dataclass)
    required: bool = True
    description: str = ""


def validate_skill_input(inp: SkillInput) -> Result[SkillInput, list[SkillValidationError]]:
    """Validate a single skill input."""
    errors: list[SkillValidationError] = []

    if not inp.name or not inp.name.strip():
        errors.append(SkillValidationError("input.name", "name cannot be empty"))

    if inp.type not in VALID_INPUT_TYPES:
        errors.append(
            SkillValidationError("input.type", f"type must be one of {VALID_INPUT_TYPES}", inp.type)
        )

    if errors:
        return Err(errors)
    return Ok(inp)


@dataclass(frozen=True)
class SkillMeta:
    """
    Metadata for a skill.

    Designed to be extracted from SKILL.md frontmatter YAML.
    All fields have defaults to allow incremental migration.
    """

    name: str
    description: str
    requires: list[str] = field(default_factory=list)
    inputs: list[SkillInput] = field(default_factory=list)
    outputs: list[str] = field(default_factory=list)
    levels: list[str] = field(default_factory=list)  # Optional: L0, L1, L2 detail levels
    source_path: str = ""  # Path to SKILL.md (for error reporting)


def validate_skill_meta(meta: SkillMeta) -> Result[SkillMeta, list[SkillValidationError]]:
    """
    Validate skill metadata.

    Returns:
        Ok(SkillMeta) if valid
        Err(list[SkillValidationError]) if invalid

    Validation rules:
        - name: non-empty string
        - description: non-empty string
        - requires: list of strings (can be empty)
        - inputs: list of valid SkillInput objects
        - outputs: list of strings (can be empty)
    """
    errors: list[SkillValidationError] = []

    # Validate name
    if not meta.name or not meta.name.strip():
        errors.append(SkillValidationError("name", "name cannot be empty"))

    # Validate description
    if not meta.description or not meta.description.strip():
        errors.append(SkillValidationError("description", "description cannot be empty"))

    # Validate requires (must be list of strings)
    for i, req in enumerate(meta.requires):
        if not isinstance(req, str):
            errors.append(
                SkillValidationError(f"requires[{i}]", "must be a string", req)
            )

    # Validate outputs (must be list of strings)
    for i, out in enumerate(meta.outputs):
        if not isinstance(out, str):
            errors.append(
                SkillValidationError(f"outputs[{i}]", "must be a string", out)
            )

    # Validate levels (must be list of strings if present)
    for i, level in enumerate(meta.levels):
        if not isinstance(level, str):
            errors.append(
                SkillValidationError(f"levels[{i}]", "must be a string", level)
            )

    # Validate inputs (must be valid SkillInput objects)
    for i, inp in enumerate(meta.inputs):
        inp_result = validate_skill_input(inp)
        if inp_result.is_err():
            # Pattern match instead of unwrap_err()
            match inp_result:
                case Err(inp_errs):
                    for inp_err in inp_errs:
                        # Prefix with input index
                        errors.append(
                            SkillValidationError(
                                f"inputs[{i}].{inp_err.field}",
                                inp_err.message,
                                inp_err.value,
                            )
                        )
                case Ok(_):
                    pass  # Already handled by is_err() check

    if errors:
        return Err(errors)

    return Ok(meta)


# Alias for backward compatibility
SkillError = SkillValidationError

