"""Daemon client for sending requests to a running DaemonRunner."""
from __future__ import annotations

import json
import socket
from pathlib import Path
from typing import Any

from src.infrastructure.daemon.protocol import MAX_REQUEST_SIZE, read_request


class DaemonClient:
    """Unix socket client for DaemonRunner RPC."""

    def __init__(self, socket_path: Path, timeout: float = 5.0) -> None:
        self._socket_path = socket_path
        self._timeout = timeout

    @property
    def socket_path(self) -> Path:
        return self._socket_path

    def is_available(self) -> bool:
        """Check if daemon socket exists."""
        return self._socket_path.exists()

    def send(self, request: dict[str, Any]) -> dict[str, Any]:
        """Send a JSON request to the daemon and return the response."""
        if not self.is_available():
            return {"status": "error", "message": "Daemon not running"}

        payload = json.dumps(request).encode("utf-8") + b"\n"
        if len(payload) > MAX_REQUEST_SIZE:
            return {"status": "error", "message": "Request too large"}

        try:
            with socket.socket(socket.AF_UNIX, socket.SOCK_STREAM) as sock:
                sock.settimeout(self._timeout)
                sock.connect(str(self._socket_path))
                sock.sendall(payload)

                read_result = read_request(sock, MAX_REQUEST_SIZE)
                if not read_result.raw_data:
                    return {"status": "error", "message": "Empty response from daemon"}

                data = read_result.raw_data.decode("utf-8", errors="replace").strip()
                return json.loads(data)
        except socket.timeout:
            return {"status": "error", "message": f"Daemon request timed out ({self._timeout}s)"}
        except ConnectionRefusedError:
            return {"status": "error", "message": "Daemon refused connection"}
        except Exception as exc:
            return {"status": "error", "message": str(exc)}

    def request(self, method: str, params: dict[str, Any]) -> dict[str, Any] | None:
        """Send an LSP method request. Returns response dict or None on error."""
        result = self.send({"method": method, "params": params})
        if result.get("status") == "ok":
            return result.get("data")
        return None

    def health(self) -> dict[str, Any]:
        """Request daemon health check."""
        return self.send({"method": "HEALTH", "params": {}})

    def shutdown(self) -> dict[str, Any]:
        """Request daemon shutdown."""
        return self.send({"method": "SHUTDOWN", "params": {}})

from typing import Any

from src.domain.lsp_contracts import FallbackReason, LSPResponse
from src.infrastructure.lsp_client import LSPState


def handle_lsp_request(req: dict[str, Any], lsp_client: Any) -> dict[str, Any]:
    """Handle JSON envelope LSP requests for daemon run."""
    method = req.get("method", "")
    params = req.get("params", {})

    if not lsp_client:
        return LSPResponse.unavailable_response(
            fallback_reason=FallbackReason.DAEMON_UNAVAILABLE,
            message="LSP client not initialized",
        ).to_dict()

    if not lsp_client.is_ready():
        return LSPResponse.degraded_response(
            fallback_reason=FallbackReason.LSP_NOT_READY,
            message=f"LSP state: {lsp_client.state.value}",
        ).to_dict()

    if lsp_client.state == LSPState.FAILED:
        return LSPResponse.degraded_response(
            fallback_reason=FallbackReason.LSP_ERROR,
            message="LSP in FAILED state",
        ).to_dict()

    # Auto-didOpen: pyright needs document open before hover/definition
    if method in ("textDocument/hover", "textDocument/definition",
                  "textDocument/references", "textDocument/completion"):
        uri = params.get("textDocument", {}).get("uri", "")
        if uri:
            from pathlib import Path as _Path
            doc_path = _Path(uri.replace("file://", ""))
            if doc_path.exists():
                lsp_client.did_open(doc_path, doc_path.read_text())

    try:
        result = lsp_client.request(method, params)
        if result:
            return LSPResponse.full_response(result).to_dict()
        return LSPResponse.degraded_response(
            fallback_reason=FallbackReason.LSP_REQUEST_TIMEOUT,
            message=f"LSP request '{method}' returned no data",
        ).to_dict()
    except Exception as exc:
        return LSPResponse.error_response(
            error_code="LSP_ERROR",
            fallback_reason=FallbackReason.LSP_ERROR,
            message=str(exc),
        ).to_dict()

import os
import socket
import stat
from pathlib import Path


def cleanup_runtime_artifacts(socket_path: Path, pid_path: Path) -> None:
    for path in (socket_path, pid_path):
        try:
            path.unlink()
        except FileNotFoundError:
            pass


def close_server(server: object | None) -> None:
    if server is None:
        return
    close_method = getattr(server, "close", None)
    if callable(close_method):
        close_method()


def create_server(socket_path: Path, pid_path: Path) -> socket.socket:
    socket_path.parent.mkdir(parents=True, exist_ok=True)
    server = socket.socket(socket.AF_UNIX, socket.SOCK_STREAM)

    try:
        if socket_path.exists():
            socket_path.unlink()
        server.bind(str(socket_path))
        os.chmod(socket_path, stat.S_IRUSR | stat.S_IWUSR)
        server.listen(1)
        server.settimeout(1.0)
        pid_path.write_text(str(os.getpid()))
    except Exception:
        close_server(server)
        cleanup_runtime_artifacts(socket_path, pid_path)
        raise

    return server

"""
Runtime Manager - Orchestrator for platform runtime.

This module provides the skeleton interface for runtime management.
Implementation comes in WO-0043.

Author: Trifecta Team
Date: 2026-03-06
"""

from abc import ABC, abstractmethod
from typing import Any


class RuntimeManager(ABC):
    """
    Abstract runtime manager for platform operations.

    Manages: daemon lifecycle, health checks, recovery operations.
    """

    @abstractmethod
    def start(self, segment_id: str) -> None:
        """Start runtime for a segment."""
        ...

    @abstractmethod
    def stop(self, segment_id: str) -> None:
        """Stop runtime for a segment."""
        ...

    @abstractmethod
    def restart(self, segment_id: str) -> None:
        """Restart runtime for a segment."""
        ...

    @abstractmethod
    def status(self, segment_id: str) -> dict[str, Any]:
        """Get runtime status for a segment."""
        ...

    @abstractmethod
    def health_check(self, segment_id: str) -> bool:
        """Perform health check for a segment."""
        ...

    @abstractmethod
    def recover(self, segment_id: str) -> None:
        """Attempt to recover a failed runtime."""
        ...


class RuntimeManagerFactory:
    """Factory for creating runtime manager instances."""

    @staticmethod
    def create(manager_type: str = "daemon", **kwargs: Any) -> RuntimeManager:
        """
        Create a runtime manager instance.

        Args:
            manager_type: Type of manager ("daemon", "embedded")
            **kwargs: Additional configuration

        Returns:
            RuntimeManager implementation instance
        """
        if manager_type == "daemon":
            from trifecta.platform.daemon_runtime import DaemonRuntimeManager

            return DaemonRuntimeManager(**kwargs)
        elif manager_type == "embedded":
            from trifecta.platform.embedded_runtime import EmbeddedRuntimeManager

            return EmbeddedRuntimeManager(**kwargs)
        else:
            raise ValueError(f"Unknown manager type: {manager_type}")

"""
Registry Protocol - Abstract interface for repository registry.

This module defines the protocol (interface) for registry operations.
Implementation (repo_store.py) comes in WO-0043.

Author: Trifecta Team
Date: 2026-03-06
"""

from abc import abstractmethod
from pathlib import Path
from typing import Any, Protocol


class Registry(Protocol):
    """
    Protocol for repository registry operations.

    All registry implementations must implement this interface.
    """

    @abstractmethod
    def register(self, repo_root: Path, metadata: dict[str, Any]) -> None:
        """Register a repository in the registry."""
        ...

    @abstractmethod
    def unregister(self, repo_id: str) -> None:
        """Remove a repository from the registry."""
        ...

    @abstractmethod
    def get(self, repo_id: str) -> dict[str, Any] | None:
        """Get repository metadata by ID."""
        ...

    @abstractmethod
    def list_all(self) -> list[dict[str, Any]]:
        """List all registered repositories."""
        ...

    @abstractmethod
    def update(self, repo_id: str, metadata: dict[str, Any]) -> None:
        """Update repository metadata."""
        ...


class RegistryFactory:
    """Factory for creating registry instances."""

    @staticmethod
    def create(registry_type: str = "sqlite", **kwargs: Any) -> Registry:
        """
        Create a registry instance.

        Args:
            registry_type: Type of registry ("sqlite", "memory")
            **kwargs: Additional configuration

        Returns:
            Registry implementation instance
        """
        if registry_type == "memory":
            from trifecta.platform.memory_registry import MemoryRegistry

            return MemoryRegistry(**kwargs)
        elif registry_type == "sqlite":
            from trifecta.platform.repo_store import SQLiteRegistry

            return SQLiteRegistry(**kwargs)
        else:
            raise ValueError(f"Unknown registry type: {registry_type}")

"""
Platform Error Definitions.

Base error classes and specific exceptions for platform operations.

Author: Trifecta Team
Date: 2026-03-06
"""

from __future__ import annotations


class PlatformError(Exception):
    """Base exception for all platform-related errors."""

    def __init__(self, message: str, **kwargs: object) -> None:
        super().__init__(message)
        self.context = kwargs


class RepoNotFoundError(PlatformError):
    """Raised when a repository cannot be found."""

    def __init__(self, repo_path: str | None = None, repo_id: str | None = None) -> None:
        if repo_path:
            message = f"Repository not found at path: {repo_path}"
        elif repo_id:
            message = f"Repository not found with id: {repo_id}"
        else:
            message = "Repository not found"
        super().__init__(message, repo_path=repo_path, repo_id=repo_id)
        self.repo_path = repo_path
        self.repo_id = repo_id


class SegmentNotFoundError(PlatformError):
    """Raised when a segment cannot be found."""

    def __init__(
        self,
        segment_path: str | None = None,
        segment_id: str | None = None,
    ) -> None:
        if segment_path:
            message = f"Segment not found at path: {segment_path}"
        elif segment_id:
            message = f"Segment not found with id: {segment_id}"
        else:
            message = "Segment not found"
        super().__init__(message, segment_path=segment_path, segment_id=segment_id)
        self.segment_path = segment_path
        self.segment_id = segment_id


class RegistryError(PlatformError):
    """Raised when a registry operation fails."""

    def __init__(self, message: str, operation: str | None = None) -> None:
        super().__init__(message, operation=operation)
        self.operation = operation


class DaemonError(PlatformError):
    """Raised when a daemon operation fails."""

    def __init__(
        self,
        message: str,
        daemon_id: str | None = None,
        operation: str | None = None,
    ) -> None:
        super().__init__(message, daemon_id=daemon_id, operation=operation)
        self.daemon_id = daemon_id
        self.operation = operation


class ConfigurationError(PlatformError):
    """Raised when configuration is invalid or missing."""

    def __init__(self, message: str, config_key: str | None = None) -> None:
        super().__init__(message, config_key=config_key)
        self.config_key = config_key

