"""Anti-split-brain test - guarantees one WO = one state file."""
from __future__ import annotations

from pathlib import Path

import pytest


def get_wo_state_files(jobs_dir: Path) -> dict[str, list[Path]]:
    """Find all WO YAML files and group by WO ID."""
    wo_files: dict[str, list[Path]] = {}
    for state in ("pending", "running", "done", "failed"):
        state_dir = jobs_dir / state
        if not state_dir.exists():
            continue
        for yaml_file in state_dir.glob("WO-*.yaml"):
            wo_id = yaml_file.stem
            if wo_id not in wo_files:
                wo_files[wo_id] = []
            wo_files[wo_id].append(yaml_file)
    return wo_files


def test_no_split_brain() -> None:
    """Invariant: each WO exists in exactly ONE state directory."""
    # Find repo root
    root = Path(__file__).resolve().parent.parent.parent
    jobs_dir = root / "_ctx" / "jobs"

    wo_files = get_wo_state_files(jobs_dir)

    duplicates = {
        wo_id: paths for wo_id, paths in wo_files.items() if len(paths) > 1
    }

    if duplicates:
        msg_lines = ["SPLIT-BRAIN DETECTED:"]
        for wo_id, paths in duplicates.items():
            paths_str = ", ".join(str(p.relative_to(root)) for p in paths)
            msg_lines.append(f"  {wo_id}: {paths_str}")
        pytest.fail("\n".join(msg_lines))


def test_no_orphan_locks() -> None:
    """Invariant: every lock has a corresponding running YAML."""
    root = Path(__file__).resolve().parent.parent.parent
    running_dir = root / "_ctx" / "jobs" / "running"

    if not running_dir.exists():
        return  # No running dir, test passes

    locks = {f.stem for f in running_dir.glob("*.lock")}
    yamls = {f.stem for f in running_dir.glob("WO-*.yaml")}

    orphan_locks = locks - yamls

    if orphan_locks:
        pytest.fail(f"ORPHAN LOCKS: {orphan_locks}")


def test_no_running_without_lock() -> None:
    """Invariant: every running WO has a lock file."""
    root = Path(__file__).resolve().parent.parent.parent
    running_dir = root / "_ctx" / "jobs" / "running"

    if not running_dir.exists():
        return

    yamls = {f.stem for f in running_dir.glob("WO-*.yaml")}
    locks = {f.stem for f in running_dir.glob("*.lock")}

    missing_locks = yamls - locks

    if missing_locks:
        pytest.fail(f"RUNNING WITHOUT LOCK: {missing_locks}")

"""Gate test: Enforce no pytest.skip in acceptance tests.

This tripwire ensures all acceptance tests are fail-closed, not skip-based.
"""

import ast
from pathlib import Path


def test_no_skip_in_acceptance_tests():
    """Verify that acceptance tests do not use pytest.skip().

    Policy: Acceptance tests must be fail-closed.
    - Use pytest.fail() for precondition failures
    - Use deterministic fixtures that guarantee preconditions
    - Use @pytest.mark.slow for environment-dependent tests

    Skip-based tests create "verde falso" (false green) in CI.
    """
    acceptance_dir = Path(__file__).parent

    violations = []

    for test_file in acceptance_dir.glob("test_*.py"):
        # Skip this meta-test file
        if test_file.name == "test_no_skip_in_acceptance.py":
            continue

        content = test_file.read_text()
        tree = ast.parse(content)

        for node in ast.walk(tree):
            # Check for pytest.skip() calls
            if isinstance(node, ast.Call):
                func = node.func

                # Pattern 1: pytest.skip(...)
                if isinstance(func, ast.Attribute):
                    if func.attr == "skip":
                        if isinstance(func.value, ast.Name) and func.value.id == "pytest":
                            violations.append(f"{test_file.name}:{node.lineno}: pytest.skip() call")

            # Check for @pytest.mark.skip decorator
            if isinstance(node, ast.FunctionDef):
                for decorator in node.decorator_list:
                    if isinstance(decorator, ast.Attribute):
                        if decorator.attr == "skip":
                            violations.append(
                                f"{test_file.name}:{node.lineno}: @pytest.mark.skip on {node.name}"
                            )
                    elif isinstance(decorator, ast.Call):
                        func = decorator.func
                        if isinstance(func, ast.Attribute) and func.attr == "skip":
                            violations.append(
                                f"{test_file.name}:{node.lineno}: @pytest.mark.skip on {node.name}"
                            )

    assert len(violations) == 0, (
        f"Found {len(violations)} skip violations in acceptance tests:\n"
        + "\n".join(f"  - {v}" for v in violations)
        + "\n\nPolicy: Use pytest.fail() or deterministic fixtures instead of pytest.skip()"
    )


def test_no_xfail_in_acceptance_tests():
    """Verify that acceptance tests do not use pytest.xfail().

    xfail creates "expected failures" that can mask real bugs.
    """
    acceptance_dir = Path(__file__).parent

    violations = []

    for test_file in acceptance_dir.glob("test_*.py"):
        if test_file.name == "test_no_skip_in_acceptance.py":
            continue

        content = test_file.read_text()
        tree = ast.parse(content)

        for node in ast.walk(tree):
            if isinstance(node, ast.Call):
                func = node.func
                if isinstance(func, ast.Attribute):
                    if func.attr == "xfail":
                        violations.append(f"{test_file.name}:{node.lineno}: pytest.xfail() call")

    assert len(violations) == 0, f"Found {len(violations)} xfail violations:\n" + "\n".join(
        f"  - {v}" for v in violations
    )

