class FakeConnection:
    def __init__(self, payload: bytes) -> None:
        self._payload = payload

    def recv(self, size: int) -> bytes:
        if not self._payload:
            return b""
        chunk = self._payload[:size]
        self._payload = self._payload[size:]
        return chunk


